/**
 * Window for browsing community loadouts: a table sortable by any column,
 * search over names, authors and sections, a section filter, a filter for
 * your own loadouts, and a preview of every setting a loadout changes.
 */
class CommunityBrowser extends JFrame
{
	private static final String[] COLUMNS = {"Name", "Author", "Published", "Sections"};

	private final InventoryHoverHighlightPlugin plugin;
	/** Why the community features cannot be used right now, or null. */
	private final Supplier<String> problem;
	/** Called with the name of a loadout added from the browser, so the side panel lists it. */
	private final Consumer<String> loadoutAdded;

	private final Model model = new Model();
	private final JTable table = new JTable(model);
	private final TableRowSorter<Model> sorter = new TableRowSorter<>(model);
	private final JTextField search = new JTextField();
	private final JButton sectionFilter = new JButton("Any sections");
	private final JCheckBox exactSections = new JCheckBox("Only these");
	/** Sections a loadout must set, or null for any; and every section seen in the list. */
	private java.util.Set<String> wantedSections;
	private final List<String> knownSections = new ArrayList<>();
	private final JCheckBox mineOnly = new JCheckBox("Mine only");
	private final JLabel status = new JLabel(" ");
	private final JLabel title = new JLabel("Pick a loadout");
	private final JLabel byline = new JLabel(" ");
	private final JTextArea preview = new JTextArea();
	private final JButton load = new JButton("Load");
	private final JButton delete = new JButton("Delete");
	private final JButton copy = new JButton("Copy JSON");

	CommunityBrowser(InventoryHoverHighlightPlugin plugin, Supplier<String> problem, Consumer<String> loadoutAdded)
	{
		super("Click Helpers - Community loadouts");
		this.plugin = plugin;
		this.problem = problem;
		this.loadoutAdded = loadoutAdded;
		setDefaultCloseOperation(HIDE_ON_CLOSE);
		setMinimumSize(new Dimension(640, 400));
		setSize(900, 560);

		JPanel root = new JPanel(new BorderLayout(0, 8));
		root.setBorder(new EmptyBorder(10, 10, 10, 10));
		root.setBackground(ColorScheme.DARK_GRAY_COLOR);
		root.add(toolbar(), BorderLayout.NORTH);

		JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, tablePane(), detailsPane());
		split.setResizeWeight(0.62);
		split.setBorder(null);
		root.add(split, BorderLayout.CENTER);

		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		root.add(status, BorderLayout.SOUTH);
		setContentPane(root);
		showSelected();
	}

	/** Opens the window and loads the list. */
	void open()
	{
		if (!isVisible())
		{
			setLocationRelativeTo(null);
		}
		setVisible(true);
		toFront();
		refresh();
	}

	/** Reloads the list if the window is open, such as after publishing. */
	void refreshIfOpen()
	{
		if (isVisible())
		{
			refresh();
		}
	}

	void refresh()
	{
		String why = problem.get();
		if (why != null)
		{
			status.setText(why);
			return;
		}
		status.setText("Loading...");
		plugin.community().list(entries ->
		{
			CommunityLoadouts.Entry selected = selected();
			model.setEntries(entries, plugin.community().uid(), plugin.loadouts().sectionNames().size());
			updateSections(entries);
			applyFilter();
			reselect(selected);
		}, status::setText);
	}

	private JPanel toolbar()
	{
		JPanel bar = new JPanel(new BorderLayout(8, 0));
		bar.setOpaque(false);

		search.setToolTipText("Search names, authors and sections");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				applyFilter();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				applyFilter();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				applyFilter();
			}
		});
		JPanel searchBox = new JPanel(new BorderLayout(6, 0));
		searchBox.setOpaque(false);
		searchBox.add(new JLabel("Search"), BorderLayout.WEST);
		searchBox.add(search, BorderLayout.CENTER);
		bar.add(searchBox, BorderLayout.CENTER);

		JPanel filters = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 0));
		filters.setOpaque(false);
		sectionFilter.setToolTipText("Only loadouts that set all the sections you pick");
		sectionFilter.addActionListener(e ->
		{
			java.util.Set<String> picked = SectionPicker.pick(this, "Filter by sections",
				"Show only loadouts that set every section you tick. Tick Only these to hide loadouts that also set other"
					+ " sections. Tick none to show every loadout.",
				knownSections, wantedSections == null ? java.util.Collections.emptySet() : wantedSections);
			if (picked != null)
			{
				wantedSections = picked.isEmpty() ? null : picked;
				sectionFilter.setText(wantedSections == null ? "Any sections"
					: wantedSections.size() + (wantedSections.size() == 1 ? " section" : " sections"));
				applyFilter();
			}
		});
		exactSections.setOpaque(false);
		exactSections.setToolTipText("Show only loadouts that set exactly the picked sections and nothing else");
		exactSections.addActionListener(e -> applyFilter());
		mineOnly.setOpaque(false);
		mineOnly.setToolTipText("Only loadouts you published");
		mineOnly.addActionListener(e -> applyFilter());
		JButton refresh = new JButton("Refresh");
		refresh.setToolTipText("Download the newest published loadouts");
		refresh.addActionListener(e -> refresh());
		filters.add(sectionFilter);
		filters.add(exactSections);
		filters.add(mineOnly);
		filters.add(refresh);
		bar.add(filters, BorderLayout.EAST);
		return bar;
	}

	private JScrollPane tablePane()
	{
		table.setRowSorter(sorter);
		sorter.setSortKeys(List.of(new RowSorter.SortKey(2, SortOrder.DESCENDING)));
		table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		table.setFillsViewportHeight(true);
		table.setRowHeight(24);
		table.setShowGrid(false);
		table.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		table.getTableHeader().setReorderingAllowed(false);
		table.getColumnModel().getColumn(0).setPreferredWidth(200);
		table.getColumnModel().getColumn(1).setPreferredWidth(140);
		table.getColumnModel().getColumn(2).setPreferredWidth(100);
		table.getColumnModel().getColumn(3).setPreferredWidth(70);
		table.setDefaultRenderer(Object.class, new Renderer());
		table.setDefaultRenderer(Date.class, new Renderer());
		table.setDefaultRenderer(Integer.class, new Renderer());
		table.getSelectionModel().addListSelectionListener(e ->
		{
			if (!e.getValueIsAdjusting())
			{
				showSelected();
			}
		});
		table.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getClickCount() == 2 && selected() != null)
				{
					loadSelected();
				}
			}
		});
		JScrollPane scroll = new JScrollPane(table);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		return scroll;
	}

	private JPanel detailsPane()
	{
		JPanel details = new JPanel(new BorderLayout(0, 6));
		details.setBorder(new EmptyBorder(0, 10, 0, 0));
		details.setOpaque(false);

		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		byline.setFont(FontManager.getRunescapeSmallFont());
		byline.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		JPanel heading = new JPanel(new GridLayout(0, 1));
		heading.setOpaque(false);
		heading.add(title);
		heading.add(byline);
		details.add(heading, BorderLayout.NORTH);

		preview.setEditable(false);
		preview.setLineWrap(true);
		preview.setWrapStyleWord(true);
		preview.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		preview.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		preview.setBorder(new EmptyBorder(6, 6, 6, 6));
		JScrollPane scroll = new JScrollPane(preview);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		details.add(scroll, BorderLayout.CENTER);

		load.setToolTipText("Add as a new loadout, or apply over your current settings (or double-click a row)");
		load.addActionListener(e -> loadSelected());
		delete.setToolTipText("Delete your published loadout");
		delete.addActionListener(e -> deleteSelected());
		copy.setToolTipText("Copy the loadout's settings JSON, to share or import elsewhere");
		copy.addActionListener(e ->
		{
			CommunityLoadouts.Entry entry = selected();
			if (entry != null)
			{
				java.awt.Toolkit.getDefaultToolkit().getSystemClipboard()
					.setContents(new java.awt.datatransfer.StringSelection(entry.settings), null);
				status.setText("Copied " + entry.name + " to the clipboard.");
			}
		});
		JPanel buttons = new JPanel(new GridLayout(1, 3, 6, 0));
		buttons.setOpaque(false);
		buttons.add(load);
		buttons.add(copy);
		buttons.add(delete);
		details.add(buttons, BorderLayout.SOUTH);
		return details;
	}

	private void applyFilter()
	{
		String text = search.getText().trim().toLowerCase();
		java.util.Set<String> wanted = wantedSections;
		boolean exact = exactSections.isSelected();
		boolean mine = mineOnly.isSelected();
		String uid = plugin.community().uid();
		sorter.setRowFilter(new RowFilter<Model, Integer>()
		{
			@Override
			public boolean include(Entry<? extends Model, ? extends Integer> row)
			{
				CommunityLoadouts.Entry entry = model.entries.get(row.getIdentifier());
				if (mine && !entry.uid.equals(uid))
				{
					return false;
				}
				if (wanted != null && (!entry.sections.containsAll(wanted)
					|| exact && entry.sections.size() != wanted.size()))
				{
					return false;
				}
				return text.isEmpty() || entry.name.toLowerCase().contains(text)
					|| entry.author().toLowerCase().contains(text)
					|| String.join(" ", entry.sections).toLowerCase().contains(text);
			}
		});
		long own = model.entries.stream().filter(e -> e.uid.equals(uid)).count();
		status.setText(table.getRowCount() + " of " + model.entries.size() + " loadouts shown. You have published "
			+ own + " of " + CommunityLoadouts.SLOTS + ".");
		showSelected();
	}

	private void updateSections(List<CommunityLoadouts.Entry> entries)
	{
		TreeSet<String> names = new TreeSet<>();
		entries.forEach(e -> names.addAll(e.sections));
		knownSections.clear();
		knownSections.addAll(names);
	}

	private CommunityLoadouts.Entry selected()
	{
		int row = table.getSelectedRow();
		return row < 0 ? null : model.entries.get(table.convertRowIndexToModel(row));
	}

	private void reselect(CommunityLoadouts.Entry previous)
	{
		if (previous == null)
		{
			return;
		}
		for (int i = 0; i < model.entries.size(); i++)
		{
			CommunityLoadouts.Entry entry = model.entries.get(i);
			if (entry.uid.equals(previous.uid) && entry.slot == previous.slot)
			{
				int view = table.convertRowIndexToView(i);
				if (view >= 0)
				{
					table.setRowSelectionInterval(view, view);
				}
				return;
			}
		}
	}

	private void showSelected()
	{
		CommunityLoadouts.Entry entry = selected();
		boolean mine = entry != null && entry.uid.equals(plugin.community().uid());
		load.setEnabled(entry != null);
		copy.setEnabled(entry != null);
		delete.setEnabled(mine);
		if (entry == null)
		{
			title.setText("Pick a loadout");
			byline.setText(" ");
			preview.setText("Select a loadout to see every setting it changes.");
			return;
		}
		title.setText(entry.name);
		byline.setText("by " + entry.author() + (mine ? " (you)" : "") + ", "
			+ new SimpleDateFormat("MMM d yyyy, HH:mm").format(new Date(entry.created)));
		preview.setText(plugin.loadouts().describe(entry.settings));
		preview.setCaretPosition(0);
	}

	private void loadSelected()
	{
		CommunityLoadouts.Entry entry = selected();
		if (entry == null)
		{
			return;
		}
		java.util.Set<String> picked = entry.sections.size() <= 1 ? null : SectionPicker.pick(this,
			"Sections to load", "Load only these sections of " + entry.name + ". Your other settings stay as they are.",
			entry.sections, null);
		if (entry.sections.size() > 1 && (picked == null || picked.isEmpty()))
		{
			return;
		}
		// Every section ticked means the whole loadout
		java.util.Set<String> sections = picked == null || picked.size() == entry.sections.size() ? null : picked;
		String scope = sections == null ? "" : " (" + sections.size() + " of " + entry.sections.size() + " sections)";

		String[] options = {"Add as new loadout", "Replace current settings", "Cancel"};
		int answer = JOptionPane.showOptionDialog(this,
			"How do you want to load " + entry + scope + "?\n\nAdd as new loadout keeps your current settings and adds"
				+ " it to your loadouts list.\nReplace current settings applies it now.",
			"Load community loadout", JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE, null, options, options[0]);
		if (answer == 0)
		{
			try
			{
				String name = plugin.loadouts().addLoadout(entry.name, plugin.loadouts().onlySections(entry.settings, sections));
				loadoutAdded.accept(name);
				status.setText("Added loadout " + name + scope + ". Load it from the Loadouts list when you want it.");
			}
			catch (RuntimeException e)
			{
				status.setText("That loadout could not be read.");
			}
		}
		else if (answer == 1)
		{
			status.setText(plugin.community().load(entry, sections));
		}
	}

	private void deleteSelected()
	{
		CommunityLoadouts.Entry entry = selected();
		String why = problem.get();
		if (entry == null || why != null)
		{
			if (why != null)
			{
				status.setText(why);
			}
			return;
		}
		int answer = JOptionPane.showConfirmDialog(this, "Delete your published loadout " + entry.name + "?",
			"Delete community loadout", JOptionPane.OK_CANCEL_OPTION);
		if (answer == JOptionPane.OK_OPTION)
		{
			plugin.community().delete(entry, message ->
			{
				status.setText(message);
				refresh();
			});
		}
	}

	/** Rows of the table, one per loadout. */
	private static class Model extends AbstractTableModel
	{
		private List<CommunityLoadouts.Entry> entries = new ArrayList<>();
		private String uid;
		/** How many sections a full loadout has, so partial ones show as a share of it. */
		private int totalSections;

		void setEntries(List<CommunityLoadouts.Entry> entries, String uid, int totalSections)
		{
			this.entries = new ArrayList<>(entries);
			this.uid = uid;
			this.totalSections = totalSections;
			fireTableDataChanged();
		}

		boolean isMine(int row)
		{
			return entries.get(row).uid.equals(uid);
		}

		@Override
		public int getRowCount()
		{
			return entries.size();
		}

		@Override
		public int getColumnCount()
		{
			return COLUMNS.length;
		}

		@Override
		public String getColumnName(int column)
		{
			return COLUMNS[column];
		}

		@Override
		public Class<?> getColumnClass(int column)
		{
			return column == 2 ? Date.class : column == 3 ? Integer.class : String.class;
		}

		@Override
		public Object getValueAt(int row, int column)
		{
			CommunityLoadouts.Entry entry = entries.get(row);
			switch (column)
			{
				case 0: return entry.name;
				case 1: return entry.author();
				case 2: return new Date(entry.created);
				default: return entry.sections.size();
			}
		}
	}

	/** Draws rows in the RuneLite colors, with your own loadouts' authors in orange. */
	private class Renderer extends DefaultTableCellRenderer
	{
		private final SimpleDateFormat format = new SimpleDateFormat("MMM d yyyy");

		@Override
		public Component getTableCellRendererComponent(JTable table, Object value, boolean isSelected,
			boolean hasFocus, int row, int column)
		{
			Object shown = value instanceof Date ? format.format((Date) value) : value;
			if (column == 3 && value instanceof Integer)
			{
				int count = (Integer) value;
				shown = model.totalSections > 0 && count >= model.totalSections ? "All"
					: count + (model.totalSections > 0 ? " of " + model.totalSections : "");
			}
			super.getTableCellRendererComponent(table, shown, isSelected, false, row, column);
			setBorder(new EmptyBorder(0, 6, 0, 6));
			boolean mine = model.isMine(table.convertRowIndexToModel(row));
			if (!isSelected)
			{
				setBackground(row % 2 == 0 ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.DARK_GRAY_COLOR);
				setForeground(column == 1 && mine ? ColorScheme.BRAND_ORANGE : Color.WHITE);
			}
			return this;
		}
	}
}

package com.inventoryhover;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;
import okhttp3.FormBody;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Loadouts that players publish for others, kept in a Firebase Realtime
 * Database. Each install signs in anonymously, which gives it an id but asks
 * the player for nothing, and may keep {@link #SLOTS} loadouts. The database
 * rules in firebase/database.rules.json enforce the slots, the name format and
 * bans. Names are checked against a public word list, downloaded on first use,
 * so the plugin ships no word list of its own.
 * Nothing is sent until the player turns the feature on and presses a button.
 */
@Singleton
class CommunityLoadouts
{
	/** Database URL from the Firebase console, like https://name-default-rtdb.firebaseio.com. Empty turns the feature off. */
	static final String DATABASE_URL = "https://click-helpers-loadouts-2b22f-default-rtdb.firebaseio.com";

	/** Web API key from the Firebase project settings. It is public by design. */
	static final String API_KEY = "AIzaSyDe8WwgmJ9zxI5cHXYB_0wudG3JjJ0uFsk";

	static final int SLOTS = 10;

	private static final int MAX_LISTED = 200;
	/** The English list of the LDNOOBW project, pinned to one commit so it cannot change under us. */
	private static final String WORD_LIST_URL = "https://cdn.jsdelivr.net/gh/LDNOOBW/"
		+ "List-of-Dirty-Naughty-Obscene-and-Otherwise-Bad-Words@5faf2ba42d7b1c0977169ec3611df25a3c08eb13/en";
	private static final String SIGN_UP_URL = "https://identitytoolkit.googleapis.com/v1/accounts:signUp";
	private static final String REFRESH_URL = "https://securetoken.googleapis.com/v1/token";
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	/** Config keys with no config item, so they never show in the panel or in exports. */
	private static final String UID_KEY = "communityUid";
	private static final String REFRESH_KEY = "communityRefreshToken";

	/** One published loadout. */
	static class Entry
	{
		final String uid;
		final int slot;
		final String name;
		final long created;
		final String settings;
		/** Names of the settings sections the loadout sets, like "Click feedback". */
		final List<String> sections;

		Entry(String uid, int slot, String name, long created, String settings, List<String> sections)
		{
			this.sections = sections;
			this.uid = uid;
			this.slot = slot;
			this.name = name;
			this.created = created;
			this.settings = settings;
		}

		String author()
		{
			return NameFilter.authorName(uid);
		}

		@Override
		public String toString()
		{
			return name + " - " + author();
		}
	}

	/** The outcome of publishing. */
	static class Result
	{
		final String message;
		/** Whether the name was refused for its words, so the panel clears it. */
		final boolean clearName;

		Result(String message, boolean clearName)
		{
			this.message = message;
			this.clearName = clearName;
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final ConfigManager configManager;
	private final SettingsSharing sharing;
	private final ScheduledExecutorService executor;

	private String idToken;
	private long idTokenExpiresAt;

	@Inject
	CommunityLoadouts(OkHttpClient http, Gson gson, ConfigManager configManager, SettingsSharing sharing,
		ScheduledExecutorService executor)
	{
		this.http = http.newBuilder().callTimeout(15, TimeUnit.SECONDS).build();
		this.gson = gson;
		this.configManager = configManager;
		this.sharing = sharing;
		this.executor = executor;
	}

	static boolean isSetUp()
	{
		return !DATABASE_URL.isEmpty() && !API_KEY.isEmpty();
	}

	/** This install's id, or null before its first publish. */
	String uid()
	{
		return configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, UID_KEY);
	}

	/** Fetches the newest published loadouts; calls back on the Swing thread. */
	void list(Consumer<List<Entry>> done, Consumer<String> failed)
	{
		executor.execute(() ->
		{
			try
			{
				// Without the list, names are only checked for length and characters
				loadWordList();
				JsonElement users = getJson(DATABASE_URL + "/users.json");
				List<Entry> entries = new ArrayList<>();
				if (users != null && users.isJsonObject())
				{
					for (Map.Entry<String, JsonElement> user : users.getAsJsonObject().entrySet())
					{
						entries.addAll(entriesOf(user.getKey(), user.getValue(), false));
					}
				}
				entries.sort(Comparator.comparingLong((Entry e) -> e.created).reversed());
				List<Entry> newest = new ArrayList<>(entries.subList(0, Math.min(MAX_LISTED, entries.size())));
				SwingUtilities.invokeLater(() -> done.accept(newest));
			}
			catch (IOException | RuntimeException e)
			{
				SwingUtilities.invokeLater(() -> failed.accept("Could not load community loadouts. Try again later."));
			}
		});
	}

	/**
	 * Publishes exported settings under a name, replacing this install's
	 * loadout with the same name; calls back on the Swing thread.
	 */
	void publish(String rawName, String settings, Consumer<Result> done)
	{
		String name = rawName == null ? "" : rawName.trim();
		String problem = NameFilter.problem(name);
		if (problem != null)
		{
			done.accept(new Result(problem, false));
			return;
		}

		if (settings == null)
		{
			done.accept(new Result("Pick a saved loadout to publish.", false));
			return;
		}
		executor.execute(() ->
		{
			Result result;
			try
			{
				result = publishNow(name, settings);
			}
			catch (IOException | RuntimeException e)
			{
				result = new Result("Could not publish right now. Try again later.", false);
			}
			Result finished = result;
			SwingUtilities.invokeLater(() -> done.accept(finished));
		});
	}

	private Result publishNow(String name, String settings) throws IOException
	{
		if (!loadWordList())
		{
			return new Result("Could not check the name right now. Try again later.", false);
		}
		if (NameFilter.isBlocked(name))
		{
			return new Result("That name is not allowed, so it was cleared. Type another name to publish under.", true);
		}

		String token = token();
		String uid = uid();
		// Hidden loadouts still take a slot, so hiding one never frees room for another
		List<Entry> mine = entriesOf(uid, getJson(DATABASE_URL + "/users/" + uid + ".json"), true);
		int slot = -1;
		for (Entry entry : mine)
		{
			if (entry.name.equalsIgnoreCase(name))
			{
				slot = entry.slot;
			}
		}
		for (int i = 0; slot == -1 && i < SLOTS; i++)
		{
			int free = i;
			if (mine.stream().noneMatch(e -> e.slot == free))
			{
				slot = free;
			}
		}
		if (slot == -1)
		{
			return new Result("You have " + SLOTS + " published loadouts. Delete one first.", false);
		}

		JsonObject body = new JsonObject();
		body.addProperty("name", name);
		JsonObject now = new JsonObject();
		now.addProperty(".sv", "timestamp");
		body.add("created", now);
		body.addProperty("settings", settings);
		Request request = new Request.Builder()
			.url(authed(DATABASE_URL + "/users/" + uid + "/" + slot + ".json", token))
			.put(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		try (Response response = http.newCall(request).execute())
		{
			if (response.code() == 401 || response.code() == 403)
			{
				return new Result("Publishing is closed right now, or this install may not publish.", false);
			}
			if (!response.isSuccessful())
			{
				return new Result("Could not publish right now. Try again later.", false);
			}
		}
		return new Result("Published " + name + " as " + NameFilter.authorName(uid) + sectionsNote(settings) + ".", false);
	}

	/** A note on which sections a loadout holds, when it holds only some of them. */
	private String sectionsNote(String settings)
	{
		List<String> sections = sectionsOf(settings);
		int all = sharing.sectionNames().size();
		if (sections.isEmpty() || sections.size() >= all)
		{
			return "";
		}
		String list = sections.size() <= 4 ? ": " + String.join(", ", sections) : "";
		return ", with only " + sections.size() + " of " + all + " sections" + list;
	}

	/** Deletes one of this install's loadouts; calls back on the Swing thread. */
	void delete(Entry entry, Consumer<String> done)
	{
		if (entry == null || !entry.uid.equals(uid()))
		{
			done.accept("You can only delete your own loadouts.");
			return;
		}

		executor.execute(() ->
		{
			String message;
			try
			{
				Request request = new Request.Builder()
					.url(authed(DATABASE_URL + "/users/" + entry.uid + "/" + entry.slot + ".json", token()))
					.delete()
					.build();
				try (Response response = http.newCall(request).execute())
				{
					message = response.isSuccessful() ? "Deleted " + entry.name + "." : "Could not delete it right now.";
				}
			}
			catch (IOException | RuntimeException e)
			{
				message = "Could not delete it right now.";
			}
			String finished = message;
			SwingUtilities.invokeLater(() -> done.accept(finished));
		});
	}

	/** Applies a published loadout; returns a message. */
	String load(Entry entry)
	{
		return load(entry, null);
	}

	/** Applies some sections of a published loadout, or all of it when {@code sections} is null; returns a message. */
	String load(Entry entry, java.util.Set<String> sections)
	{
		if (entry == null)
		{
			return "Pick a loadout to load.";
		}
		try
		{
			return "Loaded " + entry.name + " (" + sharing.importShared(entry.settings, sections) + " settings).";
		}
		catch (RuntimeException e)
		{
			return "That loadout could not be read.";
		}
	}

	/** Downloads the word list once; returns whether it is loaded. */
	private synchronized boolean loadWordList()
	{
		if (NameFilter.hasBlockedWords())
		{
			return true;
		}
		try (Response response = http.newCall(new Request.Builder().url(WORD_LIST_URL).build()).execute())
		{
			ResponseBody body = response.body();
			if (!response.isSuccessful() || body == null)
			{
				return false;
			}
			NameFilter.setBlockedWords(Arrays.asList(body.string().split("\\R")));
			return NameFilter.hasBlockedWords();
		}
		catch (IOException e)
		{
			return false;
		}
	}

	/** A current sign-in token, signing in anonymously the first time. */
	private synchronized String token() throws IOException
	{
		if (idToken != null && System.currentTimeMillis() < idTokenExpiresAt)
		{
			return idToken;
		}

		String refresh = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, REFRESH_KEY);
		if (refresh != null)
		{
			JsonObject answer = refreshSignIn(refresh);
			if (answer == null)
			{
				// The account is gone, so start over with a new one and new slots
				refresh = null;
			}
			else
			{
				idToken = answer.get("id_token").getAsString();
				refresh = answer.get("refresh_token").getAsString();
				configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, UID_KEY, answer.get("user_id").getAsString());
				idTokenExpiresAt = expiry(answer.get("expires_in"));
			}
		}
		if (refresh == null)
		{
			JsonObject answer = post(new Request.Builder()
				.url(SIGN_UP_URL + "?key=" + API_KEY)
				.post(RequestBody.create(JSON, "{\"returnSecureToken\":true}"))
				.build());
			idToken = answer.get("idToken").getAsString();
			refresh = answer.get("refreshToken").getAsString();
			configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, UID_KEY, answer.get("localId").getAsString());
			idTokenExpiresAt = expiry(answer.get("expiresIn"));
		}
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, REFRESH_KEY, refresh);
		return idToken;
	}

	/**
	 * Swaps a saved refresh token for a new sign-in. Null when Firebase refuses
	 * the token, which happens when the account was deleted or disabled.
	 */
	private JsonObject refreshSignIn(String refresh) throws IOException
	{
		Request request = new Request.Builder()
			.url(REFRESH_URL + "?key=" + API_KEY)
			.post(new FormBody.Builder()
				.add("grant_type", "refresh_token")
				.add("refresh_token", refresh)
				.build())
			.build();
		try (Response response = http.newCall(request).execute())
		{
			ResponseBody body = response.body();
			if (response.code() == 400)
			{
				return null;
			}
			if (!response.isSuccessful() || body == null)
			{
				throw new IOException("Sign-in failed: " + response.code());
			}
			return gson.fromJson(body.string(), JsonObject.class);
		}
	}

	/** When a token runs out, a minute early to be safe. */
	private static long expiry(JsonElement seconds)
	{
		long life = seconds == null ? 3600 : Long.parseLong(seconds.getAsString());
		return System.currentTimeMillis() + (life - 60) * 1000;
	}

	private JsonObject post(Request request) throws IOException
	{
		try (Response response = http.newCall(request).execute())
		{
			ResponseBody body = response.body();
			if (!response.isSuccessful() || body == null)
			{
				throw new IOException("Sign-in failed: " + response.code());
			}
			return gson.fromJson(body.string(), JsonObject.class);
		}
	}

	private JsonElement getJson(String url) throws IOException
	{
		try (Response response = http.newCall(new Request.Builder().url(url).build()).execute())
		{
			ResponseBody body = response.body();
			if (!response.isSuccessful() || body == null)
			{
				throw new IOException("Request failed: " + response.code());
			}
			return gson.fromJson(body.string(), JsonElement.class);
		}
	}

	/** The section names in exported settings, or none when they cannot be read. */
	private List<String> sectionsOf(String settings)
	{
		List<String> sections = new ArrayList<>();
		try
		{
			JsonObject root = gson.fromJson(settings, JsonObject.class);
			if (root != null && root.has("settings") && root.get("settings").isJsonObject())
			{
				for (Map.Entry<String, JsonElement> section : root.getAsJsonObject("settings").entrySet())
				{
					if (section.getValue().isJsonObject())
					{
						sections.add(section.getKey());
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			// Listed without sections
		}
		return sections;
	}

	private static HttpUrl authed(String url, String token)
	{
		return HttpUrl.parse(url).newBuilder().addQueryParameter("auth", token).build();
	}

	/**
	 * The loadouts under one install id. Unless asked for, skips hidden ones,
	 * which admins mark from the Firebase console, and any that fail the local
	 * name checks.
	 */
	private List<Entry> entriesOf(String uid, JsonElement slots, boolean all)
	{
		List<Entry> entries = new ArrayList<>();
		if (uid == null || slots == null)
		{
			return entries;
		}

		// Firebase returns keys 0 to 9 as an array, with nulls for empty slots, unless
		// few slots are used, when it returns an object keyed by slot
		Map<String, JsonElement> bySlot = new LinkedHashMap<>();
		if (slots.isJsonArray())
		{
			for (int i = 0; i < slots.getAsJsonArray().size(); i++)
			{
				bySlot.put(String.valueOf(i), slots.getAsJsonArray().get(i));
			}
		}
		else if (slots.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> slot : slots.getAsJsonObject().entrySet())
			{
				bySlot.put(slot.getKey(), slot.getValue());
			}
		}

		for (Map.Entry<String, JsonElement> slot : bySlot.entrySet())
		{
			if (slot.getValue() == null || !slot.getValue().isJsonObject())
			{
				continue;
			}
			try
			{
				JsonObject value = slot.getValue().getAsJsonObject();
				String name = value.get("name").getAsString();
				boolean hidden = value.has("hidden") && value.get("hidden").getAsBoolean();
				if (!all && (hidden || NameFilter.problem(name) != null))
				{
					continue;
				}
				String settings = value.get("settings").getAsString();
				entries.add(new Entry(uid, Integer.parseInt(slot.getKey()), name,
					value.get("created").getAsLong(), settings, sectionsOf(settings)));
			}
			catch (RuntimeException e)
			{
				// Skip anything malformed
			}
		}
		return entries;
	}
}

package com.inventoryhover;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
