	/** Starts or stops switch practice. */
	void togglePractice()
	{
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, "practiceMode", !config.practiceMode());
	}

	void clearPracticeHistory()
	{
		practiceHistory = List.of();
		configManager.unsetConfiguration(InventoryHoverHighlightConfig.GROUP, PRACTICE_HISTORY_KEY);
		refreshPanel();
	}

	/** Called by the overlay when a practice round is done. */
	void practiceRoundDone()
	{
		refreshPanel();
	}

	/** Called by the overlay when the set number of rounds is done; ends and saves the session. */
	void practiceSessionDone()
	{
		SwitchPractice.Summary summary = practice.summary();
		if (summary != null)
		{
			notify(String.format("Switch practice done: %d rounds, %.0f ms average (best %d ms),"
					+ " %.0f%% in 1 tick, %.0f%% accuracy, %d timeouts.",
				summary.rounds, summary.switchMillis, summary.bestSwitchMillis, summary.oneTickRate,
				summary.accuracy, summary.timeouts));
		}
		savePracticeSession();
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, "practiceMode", false);
		refreshPanel();
	}

	/** Ends the practice session and adds it to the history when it has a finished round. */
	private void savePracticeSession()
	{
		if (!practice.isActive())
		{
			return;
		}

		SwitchPractice.Summary summary = practice.stop();
		if (summary == null)
		{
			return;
		}

		List<SwitchPractice.Summary> history = new ArrayList<>(practiceHistory);
		history.add(summary);
		while (history.size() > PRACTICE_HISTORY_SIZE)
		{
			history.remove(0);
		}
		practiceHistory = Collections.unmodifiableList(history);
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, PRACTICE_HISTORY_KEY, gson.toJson(history));
	}

	private List<SwitchPractice.Summary> loadPracticeHistory()
	{
		String json = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, PRACTICE_HISTORY_KEY);
		if (json == null || json.isEmpty())
		{
			return List.of();
		}
		try
		{
			SwitchPractice.Summary[] sessions = gson.fromJson(json, SwitchPractice.Summary[].class);
			return sessions == null ? List.of() : List.of(sessions);
		}
		catch (JsonParseException e)
		{
			return List.of();
		}
	}

	private void refreshPanel()
	{
		ClickHelpersPanel target = panel;
		if (target == null)
		{
			return;
		}
		boolean practicing = practice.isActive();
		SwitchPractice.Summary current = practice.summary();
		List<SwitchPractice.Summary> history = practiceHistory;
		SwingUtilities.invokeLater(() -> target.update(practicing, current, history));
	}

	/** Side panel icon: a cursor dot inside a slot outline. */
	private static BufferedImage panelIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(98, 189, 125));
		g.setStroke(new BasicStroke(1.5f));
		g.drawRoundRect(1, 2, 13, 11, 4, 4);
		g.setColor(Color.WHITE);
		g.fillOval(6, 6, 4, 4);
		g.dispose();
		return image;
	}

	// Eat and drink delays

	/** Starts the eat or drink delay; returns true when the click falls in a running delay. */
	private boolean startConsumeDelay(String option, int itemId)
	{
		Consumable kind = null;
		if ("Eat".equalsIgnoreCase(option))
		{
			kind = isComboFood(itemId) ? Consumable.COMBO_FOOD : Consumable.FOOD;
		}
		else if ("Drink".equalsIgnoreCase(option))
		{
			kind = Consumable.POTION;
		}

		if (kind == null)
		{
			return false;
		}
		// A click during the delay is ignored by the game, so it does not restart the delay
		if (consumeRemaining(kind) > 0)
		{
			return true;
		}

		// Food, then a potion, then a karambwan can all go in one tick, but not in
		// another order: a potion blocks food for the rest of its tick, and a
		// karambwan blocks food for its whole delay and potions for its tick
		int tick = client.getTickCount();
		switch (kind)
		{
			case FOOD:
				extendDelay(Consumable.FOOD, tick, foodDelayTicks(client.getItemDefinition(itemId).getName()));
				break;
			case POTION:
				extendDelay(Consumable.POTION, tick, CONSUME_DELAY_TICKS);
				extendDelay(Consumable.FOOD, tick, 1);
				break;
			case COMBO_FOOD:
				extendDelay(Consumable.COMBO_FOOD, tick, CONSUME_DELAY_TICKS);
				extendDelay(Consumable.FOOD, tick, CONSUME_DELAY_TICKS);
				extendDelay(Consumable.POTION, tick, 1);
				break;
		}
		return false;
	}

	/** Makes a delay last at least {@code ticks} from {@code tick}. */
	private void extendDelay(Consumable kind, int tick, int ticks)
	{
		int[] delay = consumeDelays.get(kind);
		if (delay == null || delay[1] < tick + ticks)
		{
			consumeDelays.put(kind, new int[]{tick, tick + ticks});
		}
	}

	/**
	 * Eat delay of a food by name. Most food is 3 ticks; pies, pizzas, cakes and
	 * giant crab meat are faster.
	 */
	static int foodDelayTicks(String name)
	{
		String n = name.toLowerCase();
		boolean half = n.startsWith("half ") || n.startsWith("1/2 ");
		if (n.contains("giant crab meat"))
		{
			return 2;
		}
		if (n.endsWith(" pizza"))
		{
			return half ? 2 : 1;
		}
		if (n.endsWith(" pie"))
		{
			// Apple, meat and redberry pies take 2 ticks for the second half; members' pies 1
			boolean slowHalf = n.endsWith("apple pie") || n.endsWith("meat pie") || n.endsWith("redberry pie");
			return half && slowHalf ? 2 : 1;
		}
		if (n.equals("cake") || n.equals("2/3 cake") || n.equals("chocolate cake") || n.equals("2/3 chocolate cake"))
		{
			return 2;
		}
		return CONSUME_DELAY_TICKS;
	}

	/** Ticks left on a delay, counting the current tick as a whole one, or 0. */
	int consumeRemaining(Consumable kind)
	{
		int[] delay = consumeDelays.get(kind);
		return delay == null ? 0 : Math.max(0, delay[1] - client.getTickCount());
	}

	/** Full length in ticks of the running delay, for drawing how much is left. */
	int consumeLength(Consumable kind)
	{
		int[] delay = consumeDelays.get(kind);
		return delay == null ? CONSUME_DELAY_TICKS : Math.max(1, delay[1] - delay[0]);
	}

	/** The delay an item shares, from its inventory actions, or null. */
	Consumable consumableFor(int itemId)
	{
		return consumableCache.computeIfAbsent(itemId, id ->
		{
			ItemComposition item = client.getItemDefinition(id);
			for (String action : item.getInventoryActions())
			{
				if ("Eat".equalsIgnoreCase(action))
				{
					return isComboFood(id) ? Consumable.COMBO_FOOD : Consumable.FOOD;
				}
				if ("Drink".equalsIgnoreCase(action))
				{
					return Consumable.POTION;
				}
			}
			return null;
		});
	}

	private boolean isComboFood(int itemId)
	{
		return client.getItemDefinition(itemId).getName().toLowerCase().contains("karambwan");
	}

	// Item hiding

	private void parseItemLists()
	{
		fightActions = Text.fromCSV(config.fightActions()).stream()
			.map(String::toLowerCase)
			.collect(Collectors.toSet());
		alwaysShow = Text.fromCSV(config.alwaysShowItems());
		cuePrayers = Text.fromCSV(config.cuePrayers());
	}

	private boolean hidingActive()
	{
		return config.hideItems() && (Keybind.NOT_SET.equals(config.hideItemsHotkey()) || itemsHidden);
	}

	/** Whether an item has no fight action, so it can be hidden. */
	private boolean isNonFightItem(int itemId)
	{
		return hiddenCache.computeIfAbsent(itemId, id ->
		{
			ItemComposition item = client.getItemDefinition(id);
			String name = item.getName();
			for (String pattern : alwaysShow)
			{
				if (WildcardMatcher.matches(pattern, name))
				{
					return false;
				}
			}
			// A noted item can only be used, never eaten, drunk or worn
			if (item.getNote() != -1)
			{
				return true;
			}
			return Arrays.stream(item.getInventoryActions())
				.noneMatch(a -> a != null && fightActions.contains(a.toLowerCase()));
		});
	}

	/** Makes non-fight items transparent, or restores them when hiding is off. */
	private void updateItemHiding()
	{
		// Restore straight from the stored widgets, since a closed panel (like the
		// bank) is no longer reachable from its container
		if (!hidingActive())
		{
			if (!fadedSlots.isEmpty())
			{
				restoreItems();
			}
			return;
		}

		for (int containerId : ITEM_CONTAINERS)
		{
			Widget container = client.getWidget(containerId);
			Widget[] slots = container == null ? null : container.getDynamicChildren();
			if (slots == null)
			{
				continue;
			}

			for (Widget slot : slots)
			{
				if (slot == null)
				{
					continue;
				}

				long key = slotKey(slot);
				int itemId = slot.getItemId();
				boolean hide = !slot.isSelfHidden() && itemId > 0 && slot.getItemQuantity() > 0
					&& isNonFightItem(itemId);
				if (hide)
				{
					if (slot.getOpacity() != TRANSPARENT)
					{
						slot.setOpacity(TRANSPARENT);
					}
					fadedSlots.put(key, slot);
				}
				else if (fadedSlots.remove(key) != null)
				{
					slot.setOpacity(0);
				}
			}
		}
	}

	private void restoreItems()
	{
		for (Widget slot : fadedSlots.values())
		{
			slot.setOpacity(0);
		}
		fadedSlots.clear();
	}

	/** Whether the item in a slot is hidden by the item hiding. */
	boolean isFaded(Widget slot)
	{
		return fadedSlots.containsKey(slotKey(slot));
	}

	private static long slotKey(Widget slot)
	{
		return ((long) slot.getId() << 16) | (slot.getIndex() & 0xffff);
	}

	// Prayers

	/** Shows the game's glow again on the prayers that are active. */
	private void restorePrayerGlows()
	{
		for (int i = 0; i < PRAYER_COUNT; i++)
		{
			Widget widget = client.getWidget(InterfaceID.Prayerbook.PRAYER1 + i);
			Widget glow = findPrayerGlow(widget);
			if (glow != null)
			{
				Prayer prayer = prayerFor(widget);
				glow.setHidden(prayer == null || !isPrayerActive(prayer));
			}
		}
	}

	/** The child of a prayer widget that draws the game's active glow, or null. */
	private static Widget findPrayerGlow(Widget widget)
	{
		if (widget == null)
		{
			return null;
		}
		if (widget.getSpriteId() == ACTIVE_PRAYER_GLOW_SPRITE)
		{
			return widget;
		}

		for (Widget[] children : new Widget[][]{
			widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				Widget glow = findPrayerGlow(child);
				if (glow != null)
				{
					return glow;
				}
			}
		}
		return null;
	}

	/** The prayer a prayer tab widget belongs to, matched by its name, or null. */
	Prayer prayerFor(Widget widget)
	{
		if (widget == null || widget.getName() == null)
		{
			return null;
		}
		String key = Text.removeTags(widget.getName()).toUpperCase().replaceAll("[^A-Z0-9]+", "_");
		return PRAYERS_BY_NAME.get(key);
	}

	/** Prayer state including clicks the server has not confirmed yet. */
	boolean predictedActive(Prayer prayer)
	{
		Pending pending = pendingPrayers.get(prayer);
		return pending != null ? pending.expected : isPrayerActive(prayer);
	}

	/** Server-confirmed prayer state, unaffected by the client's predicted toggle. */
	boolean isPrayerActive(Prayer prayer)
	{
		return client.getServerVarbitValue(prayer.getVarbit()) == 1;
	}

	private void updateAutocast()
	{
		autocastComponent = -1;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int index = client.getVarbitValue(VarbitID.AUTOCAST_SPELL);
		if (index <= 0)
		{
			return;
		}

		EnumComposition spells = client.getEnum(AUTOCAST_SPELLS_ENUM);
		int spellObj = spells == null ? -1 : spells.getIntValue(index);
		if (spellObj <= 0)
		{
			return;
		}

		autocastComponent = client.getItemDefinition(spellObj).getIntValue(ParamID.SPELL_BUTTON);
	}
}

package com.inventoryhover;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Checks names of published loadouts: length, characters and blocked words.
 * The plugin ships no word list; {@link CommunityLoadouts} downloads a public
 * one and hands it over with {@link #setBlockedWords}.
 */
final class NameFilter
{
	static final int MIN_LENGTH = 3;
	static final int MAX_LENGTH = 32;

	/** Characters a name may use. The database rules use the same pattern. */
	private static final Pattern ALLOWED = Pattern.compile("^[A-Za-z0-9 '_.!?()-]+$");

	/**
	 * Blocked words this long or longer also count inside a longer word, like
	 * a word glued to "loadout". Shorter ones count only as whole words, since
	 * they hide in harmless words.
	 */
	private static final int INSIDE_WORD_LENGTH = 6;

	/** Harmless words that look like blocked ones, such as place names; never blocked. */
	private static final Set<String> HARMLESS = Set.of("therapist", "therapists", "niger");

	/**
	 * Word endings taken off before the whole-word check, so plurals and similar
	 * forms match too, with the fewest letters each must leave. Endings that
	 * also end harmless words, like the "y" of "spicy", need a longer stem.
	 */
	private static final String[] ENDINGS = {"ing", "ers", "ies", "es", "er", "ed", "y", "s"};
	private static final int[] ENDING_MIN_STEM = {4, 4, 5, 5, 4, 5, 5, 4};

	private static volatile Set<String> wholeWords = Collections.emptySet();
	private static volatile List<String> insideWords = Collections.emptyList();
	private static volatile List<String> phrases = Collections.emptyList();

	private NameFilter()
	{
	}

	/** Whether a word list is loaded, so word checks can run. */
	static boolean hasBlockedWords()
	{
		return !wholeWords.isEmpty() || !phrases.isEmpty();
	}

	/** Loads the blocked words, one word or phrase per line. */
	static void setBlockedWords(List<String> lines)
	{
		Set<String> whole = new HashSet<>();
		List<String> inside = new ArrayList<>();
		List<String> multi = new ArrayList<>();
		for (String line : lines)
		{
			List<String> words = words(line);
			if (words.isEmpty())
			{
				continue;
			}
			if (words.size() > 1)
			{
				multi.add(String.join(" ", words));
				continue;
			}
			String word = words.get(0);
			whole.add(word);
			if (word.length() >= INSIDE_WORD_LENGTH)
			{
				inside.add(word);
			}
		}
		wholeWords = whole;
		insideWords = inside;
		phrases = multi;
	}

	/**
	 * Whether a name holds a blocked word: as a whole word, inside a longer
	 * word for long blocked words, as a phrase, or spaced out letter by letter.
	 * Numbers and symbols that stand in for letters and repeated letters are
	 * evened out first.
	 */
	static boolean isBlocked(String name)
	{
		List<String> words = words(name);
		String joined = " " + String.join(" ", words) + " ";
		String letters = String.join("", words);
		if (!HARMLESS.contains(letters) && wholeWords.contains(letters))
		{
			return true;
		}
		for (String word : words)
		{
			if (HARMLESS.contains(word))
			{
				continue;
			}
			if (wholeWords.contains(word) || wholeWords.contains(stem(word)))
			{
				return true;
			}
			for (String inside : insideWords)
			{
				if (word.contains(inside))
				{
					return true;
				}
			}
		}
		for (String phrase : phrases)
		{
			if (joined.contains(" " + phrase + " ") || letters.equals(phrase.replace(" ", "")))
			{
				return true;
			}
		}
		return false;
	}

	/** The lowercase words of a text, with stand-in letters swapped back and repeated letters merged. */
	private static List<String> words(String text)
	{
		List<String> words = new ArrayList<>();
		for (String word : unleet(text.toLowerCase()).split("[^a-z]+"))
		{
			if (!word.isEmpty())
			{
				words.add(collapse(word));
			}
		}
		return words;
	}

	/** A word without its first matching ending that leaves enough letters. */
	private static String stem(String word)
	{
		for (int i = 0; i < ENDINGS.length; i++)
		{
			if (word.endsWith(ENDINGS[i]) && word.length() - ENDINGS[i].length() >= ENDING_MIN_STEM[i])
			{
				return word.substring(0, word.length() - ENDINGS[i].length());
			}
		}
		return word;
	}

	/** Merges runs of the same letter, so "baaad" reads like "bad". */
	private static String collapse(String text)
	{
		StringBuilder out = new StringBuilder(text.length());
		for (char c : text.toCharArray())
		{
			if (out.length() == 0 || out.charAt(out.length() - 1) != c)
			{
				out.append(c);
			}
		}
		return out.toString();
	}

	/** Why a name cannot be published, or null when it can. Word checks need the word list loaded. */
	static String problem(String name)
	{
		String trimmed = name == null ? "" : name.trim();
		if (trimmed.length() < MIN_LENGTH || trimmed.length() > MAX_LENGTH)
		{
			return "Names are " + MIN_LENGTH + " to " + MAX_LENGTH + " characters long.";
		}
		if (!ALLOWED.matcher(trimmed).matches())
		{
			return "Names can use letters, numbers, spaces and ' _ . ! ? ( ) - only.";
		}
		if (isBlocked(trimmed))
		{
			return "That name is not allowed.";
		}
		return null;
	}

	/** Swaps numbers and symbols that stand in for letters, so "n4me" reads as "name". */
	private static String unleet(String text)
	{
		StringBuilder out = new StringBuilder(text.length());
		for (char c : text.toCharArray())
		{
			switch (c)
			{
				case '0': out.append('o'); break;
				case '1': case '!': out.append('i'); break;
				case '3': out.append('e'); break;
				case '4': case '@': out.append('a'); break;
				case '5': case '$': out.append('s'); break;
				case '7': out.append('t'); break;
				case '8': out.append('b'); break;
				default: out.append(c);
			}
		}
		return out.toString();
	}

	/** A fixed author name for an install id, like "Swift Goblin 42", so players never type one. */
	static String authorName(String uid)
	{
		String[] adjectives = {"Swift", "Brave", "Quiet", "Lucky", "Clever", "Steady", "Bold", "Calm",
			"Sharp", "Nimble", "Mighty", "Sly", "Keen", "Gentle", "Rapid", "Patient"};
		String[] creatures = {"Goblin", "Imp", "Cow", "Chicken", "Rat", "Spider", "Troll", "Gnome",
			"Dwarf", "Ogre", "Wolf", "Bat", "Frog", "Penguin", "Monk", "Wizard"};
		int hash = uid == null ? 0 : uid.hashCode() & 0x7fffffff;
		return adjectives[hash % adjectives.length] + " " + creatures[(hash / 16) % creatures.length]
			+ " " + (hash / 256) % 100;
	}
}

package com.inventoryhover;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * The switch practice status and stats in a normal RuneLite box, so it can be
 * moved with Alt+drag like other overlays. Starts above the inventory.
 */
class PracticeStatusOverlay extends OverlayPanel
{
	private final InventoryHoverHighlightOverlay overlay;

	@Inject
	PracticeStatusOverlay(InventoryHoverHighlightOverlay overlay)
	{
		this.overlay = overlay;
		setPosition(OverlayPosition.BOTTOM_RIGHT);
		panelComponent.setPreferredSize(new Dimension(230, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<String> lines = overlay.practiceLines();
		if (lines.isEmpty())
		{
			return null;
		}
		for (String line : lines)
		{
			panelComponent.getChildren().add(LineComponent.builder().left(line).build());
		}
		return super.render(graphics);
	}
}

package com.inventoryhover;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;

/** A dialog of checkboxes for picking settings sections. */
final class SectionPicker
{
	private SectionPicker()
	{
	}

	/**
	 * Asks which of the sections to use. Returns the picked sections, or null
	 * when the dialog was cancelled. {@code selected} null ticks every box.
	 */
	static Set<String> pick(Component parent, String title, String note, List<String> names, Set<String> selected)
	{
		JPanel boxes = new JPanel(new GridLayout(0, 1));
		List<JCheckBox> checks = new ArrayList<>();
		for (String name : names)
		{
			JCheckBox check = new JCheckBox(name, selected == null || selected.contains(name));
			checks.add(check);
			boxes.add(check);
		}
		JPanel quick = new JPanel(new GridLayout(1, 2, 6, 0));
		JButton all = new JButton("All");
		all.addActionListener(e -> checks.forEach(c -> c.setSelected(true)));
		JButton none = new JButton("None");
		none.addActionListener(e -> checks.forEach(c -> c.setSelected(false)));
		quick.add(all);
		quick.add(none);

		JPanel content = new JPanel(new BorderLayout(0, 6));
		content.add(new JLabel("<html><body style='width: 240px'>" + note + "</body></html>"), BorderLayout.NORTH);
		JScrollPane scroll = new JScrollPane(boxes);
		scroll.setPreferredSize(new Dimension(260, Math.min(320, 28 * names.size() + 10)));
		content.add(scroll, BorderLayout.CENTER);
		content.add(quick, BorderLayout.SOUTH);

		int answer = JOptionPane.showConfirmDialog(parent, content, title, JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.PLAIN_MESSAGE);
		if (answer != JOptionPane.OK_OPTION)
		{
			return null;
		}
		Set<String> picked = new LinkedHashSet<>();
		checks.stream().filter(JCheckBox::isSelected).forEach(c -> picked.add(c.getText()));
		return picked;
	}
}

package com.inventoryhover;

import java.util.List;

/**
 * The settings sections, in the order the side panel shows them. Their names
 * are also the group names in exported and published settings, so they must
 * not change. Only the import/export section is still a RuneLite config
 * section; every other setting is hidden from RuneLite's panel and edited in
 * the side panel instead.
 */
final class SettingsSections
{
	/** One section: its key, as in each setting's section, and its shown name. */
	static final class Section
	{
		final String key;
		final String name;
		final String description;

		Section(String key, String name, String description)
		{
			this.key = key;
			this.name = name;
			this.description = description;
		}
	}

	static final List<Section> ALL = List.of(
		new Section(InventoryHoverHighlightConfig.areasSection, "Areas", "Where the highlight and clickable grid are shown"),
		new Section(InventoryHoverHighlightConfig.clickSection, "Click feedback", "Flash and marker on the slot you click"),
		new Section(InventoryHoverHighlightConfig.missSection, "Missed clicks", "Markers for clicks that do nothing or are refused"),
		new Section(InventoryHoverHighlightConfig.deadSection, "Dead areas", "Shading over the gaps where a click does nothing, per panel"),
		new Section(InventoryHoverHighlightConfig.prayerSection, "Prayers and spells", "Active prayer, selected spell and autocast highlights"),
		new Section(InventoryHoverHighlightConfig.tickSection, "Tick cue", "Timing cue on prayers to help with prayer flicking"),
		new Section(InventoryHoverHighlightConfig.chartSection, "Click chart", "Floating chart of your recent good, missed, refused and double clicks"),
		new Section(InventoryHoverHighlightConfig.itemsSection, "Hide items", "Hide items you do not click in a fight"),
		new Section(InventoryHoverHighlightConfig.delaySection, "Eat and drink delay", "Shade food and potions while another one would be ignored"),
		new Section(InventoryHoverHighlightConfig.practiceSection, "Switch practice", "Hotkey for switch practice; the other practice settings are in the Click Helpers side panel"),
		new Section(InventoryHoverHighlightConfig.shareSection, "Import/export settings", "Export all settings to the clipboard as JSON, import shared JSON settings, and the side panel"),
		new Section(InventoryHoverHighlightConfig.invHoverSection, "Inventory: hover", "Inventory and bank inventory hover settings"),
		new Section(InventoryHoverHighlightConfig.invSpotlightSection, "Inventory: spotlight", "Inventory and bank inventory spotlight settings"),
		new Section(InventoryHoverHighlightConfig.invMissDotsSection, "Inventory: miss dots", "Inventory and bank inventory miss dots settings"),
		new Section(InventoryHoverHighlightConfig.prayerHoverSection, "Prayer: hover", "Prayer tab hover settings"),
		new Section(InventoryHoverHighlightConfig.prayerSpotlightSection, "Prayer: spotlight", "Prayer tab spotlight settings"),
		new Section(InventoryHoverHighlightConfig.prayerMissDotsSection, "Prayer: miss dots", "Prayer tab miss dots settings"),
		new Section(InventoryHoverHighlightConfig.spellHoverSection, "Spellbook: hover", "Spellbook hover settings"),
		new Section(InventoryHoverHighlightConfig.spellSpotlightSection, "Spellbook: spotlight", "Spellbook spotlight settings"),
		new Section(InventoryHoverHighlightConfig.spellMissDotsSection, "Spellbook: miss dots", "Spellbook miss dots settings")
	);

	private SettingsSections()
	{
	}

	/** The shown name of a section key, or null when there is no such section. */
	static String nameOf(String key)
	{
		for (Section section : ALL)
		{
			if (section.key.equals(key))
			{
				return section.name;
			}
		}
		return null;
	}
}

package com.inventoryhover;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.awt.Color;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigDescriptor;
import net.runelite.client.config.ConfigItemDescriptor;
import net.runelite.client.config.ConfigManager;

/**
 * Copies the plugin's settings to the clipboard as readable JSON, grouped by
 * settings section, and applies settings pasted back from the clipboard. Uses
 * only the clipboard and the config manager, never files.
 */
@Singleton
class SettingsSharing
{
	private static final String EXPORT_MARKER = "click-helpers";
	private static final int EXPORT_VERSION = 1;
	private static final int MAX_IMPORT_CHARS = 64 * 1024;

	/** Config key holding the loadouts as a JSON object of name to exported settings. */
	private static final String LOADOUTS_KEY = "loadouts";

	/** Config key holding the name of the loadout last saved or loaded. */
	private static final String CURRENT_KEY = "currentLoadout";

	/** Settings that start something and must never be copied or pasted. */
	private static final Set<String> SKIPPED_KEYS = Set.of("copySettings", "pasteSettings", "practiceMode",
		// A shared loadout must never turn on network features for whoever loads it
		"communityLoadouts",
		// Personal choices that a loadout should not change for whoever loads it
		"syncTabSettings", "sidePanel");

	private static final List<String> TAB_PREFIXES = TabSettings.PREFIXES;

	private final InventoryHoverHighlightConfig config;
	private final ConfigManager configManager;

	/** Whether settings are being imported, which pauses tab sync. */
	private boolean importing;

	/** Keys of the tab settings, found on first use. */
	private Set<String> tabKeys;
	private final Gson gson;

	@Inject
	SettingsSharing(InventoryHoverHighlightConfig config, ConfigManager configManager, Gson gson)
	{
		this.config = config;
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Copies the settings to the clipboard; returns a message for the player. */
	String copyToClipboard()
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(exportJson()), null);
		return "Click Helpers settings exported to the clipboard.";
	}

	/** Applies settings from the clipboard; returns a message for the player. */
	String pasteFromClipboard()
	{
		String json;
		try
		{
			json = (String) Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.stringFlavor);
		}
		catch (Exception e)
		{
			return "Nothing to import: the clipboard has no text.";
		}

		if (json == null || json.length() > MAX_IMPORT_CHARS)
		{
			return "The clipboard does not hold Click Helpers settings.";
		}

		try
		{
			return "Imported " + importJson(json) + " Click Helpers settings.";
		}
		catch (RuntimeException e)
		{
			return "The clipboard does not hold Click Helpers settings.";
		}
	}

	/**
	 * Every setting of this plugin with its current value, grouped under its
	 * settings section name in the order the config panel shows them, so the
	 * export reads like the panel. Settings still at their default are included
	 * too, so loading the export sets every setting of its sections. With
	 * {@code onlySections}, only those sections are included.
	 */
	private JsonObject currentSettings(Set<String> onlySections)
	{
		ConfigDescriptor descriptor = configManager.getConfigDescriptor(config);
		Map<String, String> sectionNames = new HashMap<>();
		JsonObject settings = new JsonObject();
		for (SettingsSections.Section section : SettingsSections.ALL)
		{
			sectionNames.put(section.key, section.name);
			settings.add(section.name, new JsonObject());
		}

		descriptor.getItems().stream()
			.sorted(Comparator.comparingInt(ConfigItemDescriptor::position))
			.filter(item -> !SKIPPED_KEYS.contains(item.key()))
			.forEach(item ->
			{
				String section = sectionNames.getOrDefault(item.getItem().section(), "Other");
				if (onlySections != null && !onlySections.contains(section))
				{
					return;
				}
				String value = effectiveValue(item);
				if (value == null)
				{
					return;
				}
				if (!settings.has(section))
				{
					settings.add(section, new JsonObject());
				}
				settings.getAsJsonObject(section).addProperty(item.key(), value);
			});

		// Leave out sections with nothing in them
		for (String section : new ArrayList<>(settings.keySet()))
		{
			if (settings.getAsJsonObject(section).size() == 0)
			{
				settings.remove(section);
			}
		}
		return settings;
	}

	/** Names of the settings sections that can be saved, in config panel order. */
	List<String> sectionNames()
	{
		return new ArrayList<>(currentSettings(null).keySet());
	}

	/** Whether every setting's default has been stored, so each one can be read like a changed one. */
	private boolean defaultsStored;

	/**
	 * A setting's current value as stored text. Defaults are stored once with
	 * RuneLite's own call, which only fills in settings that were never changed.
	 */
	private String effectiveValue(ConfigItemDescriptor item)
	{
		if (!defaultsStored)
		{
			configManager.setDefaultConfiguration(config, false);
			defaultsStored = true;
		}
		String value = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, item.key());
		if (value == null)
		{
			// Reset since the defaults were stored, so store them again
			configManager.setDefaultConfiguration(config, false);
		}
		return value != null ? value : configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, item.key());
	}


	/** Copies a changed tab setting to the same setting of the other tabs; other keys are ignored. */
	void syncTabSetting(String key, String value)
	{
		if (importing)
		{
			return;
		}
		String prefix = tabPrefixOf(key);
		if (prefix == null)
		{
			return;
		}

		String suffix = key.substring(prefix.length());
		for (String other : TAB_PREFIXES)
		{
			String target = other + suffix;
			// Stop when the value already matches, so the change events of the copies end here
			if (other.equals(prefix) || Objects.equals(value, configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, target)))
			{
				continue;
			}
			if (value == null)
			{
				configManager.unsetConfiguration(InventoryHoverHighlightConfig.GROUP, target);
			}
			else
			{
				configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, target, value);
			}
		}
	}

	/** Copies every inventory tab setting to the other tabs. */
	void syncAllTabs()
	{
		for (String key : tabKeys())
		{
			if (key.startsWith(TabSettings.INVENTORY))
			{
				syncTabSetting(key, configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, key));
			}
		}
	}

	/** The tab prefix of a tab setting key, or null for any other key. */
	private String tabPrefixOf(String key)
	{
		if (!tabKeys().contains(key))
		{
			return null;
		}
		for (String prefix : TAB_PREFIXES)
		{
			if (key.startsWith(prefix))
			{
				return prefix;
			}
		}
		return null;
	}

	/** Keys of every setting in a tab section. Matched by section, since general keys like "prayers" share a prefix. */
	private Set<String> tabKeys()
	{
		if (tabKeys == null)
		{
			Set<String> sections = TabSettings.SECTIONS;
			tabKeys = configManager.getConfigDescriptor(config).getItems().stream()
				.filter(item -> sections.contains(item.getItem().section()))
				.map(ConfigItemDescriptor::key)
				.collect(Collectors.toSet());
		}
		return tabKeys;
	}

	private Set<String> settingKeys()
	{
		return configManager.getConfigDescriptor(config).getItems().stream()
			.map(ConfigItemDescriptor::key)
			.filter(key -> !SKIPPED_KEYS.contains(key))
			.collect(Collectors.toSet());
	}

	/** Sections randomize leaves alone: the click chart and the import/export switches. */
	private static final Set<String> NOT_RANDOMIZED_SECTIONS = Set.of(InventoryHoverHighlightConfig.chartSection,
		InventoryHoverHighlightConfig.shareSection);

	/**
	 * Sets every on/off, number, color and choice setting to a random value,
	 * with each tab randomized on its own; returns a message. The click chart,
	 * import/export switches, hotkeys, text lists and hidden settings stay.
	 */
	String randomizeAll()
	{
		Random random = new Random();
		// Sync would copy each tab's random values over the others, so turn it off first
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, "syncTabSettings", false);
		int changed = 0;
		for (ConfigItemDescriptor item : configManager.getConfigDescriptor(config).getItems())
		{
			// Practice settings are kept as they are; the side panel's practice tab sets them
			// Off with empty inventory would look like the plugin broke, so it is left as it is
			if (SKIPPED_KEYS.contains(item.key()) || item.key().equals("hideWhenEmpty")
				|| item.key().startsWith("practice")
				|| NOT_RANDOMIZED_SECTIONS.contains(item.getItem().section()))
			{
				continue;
			}

			Object value;
			Type type = item.getType();
			if (type == boolean.class || type == Boolean.class)
			{
				value = random.nextBoolean();
			}
			else if (type == int.class || type == Integer.class)
			{
				int min = item.getRange() == null ? 0 : item.getRange().min();
				int max = item.getRange() == null ? 100 : Math.min(item.getRange().max(), 100_000);
				value = min + random.nextInt(Math.max(1, max - min + 1));
			}
			else if (type == Color.class)
			{
				value = new Color(random.nextInt(256), random.nextInt(256), random.nextInt(256),
					item.getAlpha() == null ? 255 : 40 + random.nextInt(216));
			}
			else if (type instanceof Class && ((Class<?>) type).isEnum())
			{
				Object[] options = ((Class<?>) type).getEnumConstants();
				value = options[random.nextInt(options.length)];
			}
			else
			{
				continue;
			}
			configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, item.key(), value);
			changed++;
		}
		return "Randomized " + changed + " settings and turned off tab sync. Load a loadout to go back.";
	}

	// Loadouts: named snapshots of every setting, kept in the plugin's own config, never in files

	/** Loadout names, in the order they were saved. */
	List<String> loadoutNames()
	{
		return new ArrayList<>(loadouts().keySet());
	}

	/** Saves every current setting under a name, replacing a loadout with that name; returns a message. */
	String saveLoadout(String name)
	{
		return saveLoadout(name, null);
	}

	/**
	 * Saves the current settings of some sections under a name, replacing a
	 * loadout with that name; returns a message. Loading it later only changes
	 * those sections. All sections when {@code sections} is null.
	 */
	String saveLoadout(String name, Set<String> sections)
	{
		name = name == null ? "" : name.trim();
		if (name.isEmpty())
		{
			return "Type a name for the loadout first.";
		}
		JsonObject all = loadouts();
		boolean replaced = all.has(name);
		if (sections != null && sections.isEmpty())
		{
			return "Pick at least one section to save.";
		}
		all.add(name, gson.fromJson(exportJson(sections), JsonObject.class));
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, LOADOUTS_KEY, gson.toJson(all));
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, CURRENT_KEY, name);
		String scope = sections == null ? "" : " with " + sections.size() + (sections.size() == 1 ? " section" : " sections");
		return (replaced ? "Updated loadout " : "Saved loadout ") + name + scope + ".";
	}

	/** Applies a saved loadout; returns a message. */
	String loadLoadout(String name)
	{
		return loadLoadout(name, null);
	}

	/** Applies some sections of a saved loadout, or all of them when {@code sections} is null; returns a message. */
	String loadLoadout(String name, Set<String> sections)
	{
		JsonObject all = loadouts();
		if (name == null || !all.has(name))
		{
			return "Pick a loadout to load.";
		}
		int applied = importJson(onlySections(gson.toJson(all.get(name)), sections));
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, CURRENT_KEY, name);
		return "Loaded loadout " + name + " (" + applied + " settings).";
	}

	/** Deletes a saved loadout; returns a message. */
	String deleteLoadout(String name)
	{
		JsonObject all = loadouts();
		if (name == null || all.remove(name) == null)
		{
			return "Pick a loadout to delete.";
		}
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, LOADOUTS_KEY, gson.toJson(all));
		if (name.equals(currentLoadout()))
		{
			configManager.unsetConfiguration(InventoryHoverHighlightConfig.GROUP, CURRENT_KEY);
		}
		return "Deleted loadout " + name + ".";
	}

	/** The loadout last saved or loaded, or null. */
	String currentLoadout()
	{
		String name = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, CURRENT_KEY);
		return name != null && loadouts().has(name) ? name : null;
	}

	/** The saved settings of a loadout as compact JSON, or null when there is no such loadout. */
	String loadoutJson(String name)
	{
		JsonObject all = loadouts();
		return name != null && all.has(name) ? gson.toJson(all.get(name)) : null;
	}

	/**
	 * Saves exported settings, such as a community loadout, as a new loadout
	 * without applying them. Picks a free name based on the one given; returns
	 * the name used.
	 */
	String addLoadout(String name, String json)
	{
		JsonObject settings = json == null || json.length() > MAX_IMPORT_CHARS ? null : gson.fromJson(json, JsonObject.class);
		if (settings == null || !settings.has("plugin") || !EXPORT_MARKER.equals(settings.get("plugin").getAsString()))
		{
			throw new JsonParseException("Not Click Helpers settings");
		}
		JsonObject all = loadouts();
		String base = name == null || name.trim().isEmpty() ? "Community loadout" : name.trim();
		String free = base;
		for (int i = 2; all.has(free); i++)
		{
			free = base + " (" + i + ")";
		}
		all.add(free, settings);
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, LOADOUTS_KEY, gson.toJson(all));
		return free;
	}

	private JsonObject loadouts()
	{
		String json = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, LOADOUTS_KEY);
		try
		{
			JsonObject all = json == null ? null : gson.fromJson(json, JsonObject.class);
			return all == null ? new JsonObject() : all;
		}
		catch (JsonParseException e)
		{
			return new JsonObject();
		}
	}

	/**
	 * A readable list of the settings in exported JSON, grouped by section, with
	 * each setting's name from the config panel. Settings this version does not
	 * know are counted, since importing skips them.
	 */
	String describe(String json)
	{
		JsonObject root;
		try
		{
			root = gson.fromJson(json, JsonObject.class);
		}
		catch (JsonParseException e)
		{
			return "These settings could not be read.";
		}
		if (root == null || !root.has("settings") || !root.get("settings").isJsonObject())
		{
			return "These settings could not be read.";
		}

		Map<String, ConfigItemDescriptor> items = new HashMap<>();
		for (ConfigItemDescriptor item : configManager.getConfigDescriptor(config).getItems())
		{
			items.put(item.key(), item);
		}

		StringBuilder out = new StringBuilder();
		int unknown = 0;
		for (Map.Entry<String, JsonElement> section : root.getAsJsonObject("settings").entrySet())
		{
			if (!section.getValue().isJsonObject())
			{
				continue;
			}
			StringBuilder lines = new StringBuilder();
			for (Map.Entry<String, JsonElement> setting : section.getValue().getAsJsonObject().entrySet())
			{
				ConfigItemDescriptor item = items.get(setting.getKey());
				if (item == null || SKIPPED_KEYS.contains(setting.getKey()) || !setting.getValue().isJsonPrimitive())
				{
					unknown++;
					continue;
				}
				lines.append("  ").append(item.name()).append(": ")
					.append(readable(item, setting.getValue().getAsString())).append('\n');
			}
			if (lines.length() > 0)
			{
				out.append(section.getKey()).append('\n').append(lines).append('\n');
			}
		}
		if (unknown > 0)
		{
			out.append(unknown).append(" settings this version does not have will be skipped.");
		}
		return out.length() == 0 ? "This loadout sets nothing." : out.toString().trim();
	}

	/** A stored setting value as the config panel would show it. */
	private static String readable(ConfigItemDescriptor item, String value)
	{
		Type type = item.getType();
		if (type == boolean.class || type == Boolean.class)
		{
			return Boolean.parseBoolean(value) ? "On" : "Off";
		}
		if (type == Color.class)
		{
			try
			{
				Color color = new Color((int) Long.parseLong(value), true);
				return String.format("#%02X%02X%02X, %d%% opaque", color.getRed(), color.getGreen(), color.getBlue(),
					Math.round(color.getAlpha() * 100 / 255f));
			}
			catch (NumberFormatException e)
			{
				return value;
			}
		}
		if (type instanceof Class && ((Class<?>) type).isEnum())
		{
			String words = value.replace('_', ' ').toLowerCase();
			return words.isEmpty() ? value : Character.toUpperCase(words.charAt(0)) + words.substring(1);
		}
		return value;
	}

	/**
	 * Exported settings cut down to some sections, or unchanged when
	 * {@code sections} is null. Settings outside any section are dropped too.
	 */
	String onlySections(String json, Set<String> sections)
	{
		if (json == null || sections == null)
		{
			return json;
		}
		JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root == null || !root.has("settings") || !root.get("settings").isJsonObject())
		{
			return json;
		}
		JsonObject kept = new JsonObject();
		for (Map.Entry<String, JsonElement> section : root.getAsJsonObject("settings").entrySet())
		{
			if (section.getValue().isJsonObject() && sections.contains(section.getKey()))
			{
				kept.add(section.getKey(), section.getValue());
			}
		}
		root.add("settings", kept);
		return gson.toJson(root);
	}

	/** Applies settings from a published loadout; returns how many were applied. Unknown keys are skipped. */
	int importShared(String json, Set<String> sections)
	{
		return importShared(onlySections(json, sections));
	}

	int importShared(String json)
	{
		if (json == null || json.length() > MAX_IMPORT_CHARS)
		{
			throw new JsonParseException("Not Click Helpers settings");
		}
		return importJson(json);
	}

	private String exportJson()
	{
		return exportJson(null);
	}

	private String exportJson(Set<String> sections)
	{
		JsonObject root = new JsonObject();
		root.addProperty("plugin", EXPORT_MARKER);
		root.addProperty("version", EXPORT_VERSION);
		root.add("settings", currentSettings(sections));
		return gson.newBuilder().setPrettyPrinting().create().toJson(root);
	}

	/**
	 * Applies exported settings; returns how many were applied. Settings may be
	 * grouped by section or flat. Unknown keys are skipped.
	 */
	private int importJson(String json)
	{
		JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root == null || !root.has("plugin") || !EXPORT_MARKER.equals(root.get("plugin").getAsString())
			|| !root.has("settings") || !root.get("settings").isJsonObject())
		{
			throw new JsonParseException("Not Click Helpers settings");
		}

		Map<String, String> values = new HashMap<>();
		for (Map.Entry<String, JsonElement> entry : root.getAsJsonObject("settings").entrySet())
		{
			if (entry.getValue().isJsonObject())
			{
				for (Map.Entry<String, JsonElement> inner : entry.getValue().getAsJsonObject().entrySet())
				{
					if (inner.getValue().isJsonPrimitive())
					{
						values.put(inner.getKey(), inner.getValue().getAsString());
					}
				}
			}
			else if (entry.getValue().isJsonPrimitive())
			{
				values.put(entry.getKey(), entry.getValue().getAsString());
			}
		}

		Set<String> known = settingKeys();
		int applied = 0;
		// Each setting's change event would otherwise copy it over the other tabs before their own values land
		importing = true;
		try
		{
			for (Map.Entry<String, String> entry : values.entrySet())
			{
				if (known.contains(entry.getKey()))
				{
					configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, entry.getKey(), entry.getValue());
					applied++;
				}
			}
		}
		finally
		{
			importing = false;
		}
		return applied;
	}
}

