/**
 * The plugin's settings, edited in the side panel: every setting grouped in
 * collapsible sections, a search box that filters them as you type, and
 * fields that update the moment a setting changes anywhere, such as by tab
 * sync. Settings are read and saved through the config manager, as RuneLite's
 * own panel does; they are hidden from that panel so they live in one place.
 */
class SettingsView extends JPanel
{
	/** Shown in RuneLite's panel instead. */
	private static final Set<String> NOT_LISTED_SECTIONS = Set.of(InventoryHoverHighlightConfig.shareSection);

	/** Set on the side panel's Practice tab instead; the practice hotkey is listed here. */
	private static final Set<String> PRACTICE_TAB_KEYS = Set.of("practiceMode", "practiceTargets", "practiceRoundDelay",
		"practiceRandomDelay", "practiceTargetColor", "practiceHitColor", "practiceTimeLimitSeconds", "practiceTimerBar",
		"practiceRounds", "practiceOrdered", "practiceNumbers", "practiceStatsMode");
	private static final String GENERAL = "General";

	private final ConfigManager configManager;
	private final InventoryHoverHighlightConfig config;
	private final ColorPickerManager colorPickerManager;

	private final JTextField search = new JTextField();
	private final JPanel list = new JPanel();
	private final List<SectionBox> sections = new ArrayList<>();
	/** Puts each setting's stored value into its field. */
	private final Map<String, Runnable> refreshers = new HashMap<>();
	/** Set while fields are being filled in, so that doing so saves nothing. */
	private boolean updating;

	/** One collapsible section and its setting rows. */
	private static class SectionBox
	{
		final String name;
		final JPanel panel = new JPanel(new BorderLayout());
		final JButton header = new JButton();
		final JPanel contents = new JPanel();
		final List<Row> rows = new ArrayList<>();
		boolean open;

		SectionBox(String name)
		{
			this.name = name;
		}
	}

	/** One setting's row, with the text it can be found by. */
	private static class Row
	{
		final JComponent panel;
		final String text;

		Row(JComponent panel, String text)
		{
			this.panel = panel;
			this.text = text;
		}
	}

	SettingsView(ConfigManager configManager, InventoryHoverHighlightConfig config, ColorPickerManager colorPickerManager)
	{
		this.configManager = configManager;
		this.config = config;
		this.colorPickerManager = colorPickerManager;
		setLayout(new BorderLayout(0, 6));
		// Settings never changed have no stored value yet; store their defaults so each one can be read
		configManager.setDefaultConfiguration(config, false);

		JPanel top = new JPanel(new BorderLayout(0, 6));
		search.setToolTipText("Type to show only the settings whose name, description or section matches");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				applyFilter();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				applyFilter();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				applyFilter();
			}
		});
		JPanel searchRow = new JPanel(new BorderLayout(6, 0));
		searchRow.add(small(new JLabel("Search")), BorderLayout.WEST);
		searchRow.add(search, BorderLayout.CENTER);
		top.add(searchRow, BorderLayout.NORTH);

		JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
		JButton expand = new JButton("Expand all");
		expand.addActionListener(e -> setAllOpen(true));
		JButton collapse = new JButton("Collapse all");
		collapse.addActionListener(e -> setAllOpen(false));
		buttons.add(expand);
		buttons.add(collapse);
		top.add(buttons, BorderLayout.SOUTH);
		add(top, BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		add(list, BorderLayout.CENTER);
		build();
	}

	/** Shows a setting's new stored value; safe to call from any thread. */
	void settingChanged(String key)
	{
		Runnable refresher = refreshers.get(key);
		if (refresher != null)
		{
			SwingUtilities.invokeLater(() ->
			{
				updating = true;
				try
				{
					refresher.run();
				}
				finally
				{
					updating = false;
				}
			});
		}
	}

	/** Shows every setting's stored value, such as after loading a loadout. */
	void refreshAll()
	{
		new ArrayList<>(refreshers.keySet()).forEach(this::settingChanged);
	}

	private void build()
	{
		Map<String, List<ConfigItemDescriptor>> bySection = new LinkedHashMap<>();
		bySection.put("", new ArrayList<>());
		for (SettingsSections.Section section : SettingsSections.ALL)
		{
			bySection.put(section.key, new ArrayList<>());
		}
		configManager.getConfigDescriptor(config).getItems().stream()
			.sorted(Comparator.comparingInt(ConfigItemDescriptor::position))
			.forEach(item ->
			{
				String section = item.getItem().section();
				if (NOT_LISTED_SECTIONS.contains(section) || PRACTICE_TAB_KEYS.contains(item.key()))
				{
					return;
				}
				bySection.computeIfAbsent(bySection.containsKey(section) ? section : "", k -> new ArrayList<>()).add(item);
			});

		for (Map.Entry<String, List<ConfigItemDescriptor>> entry : bySection.entrySet())
		{
			if (entry.getValue().isEmpty())
			{
				continue;
			}
			String name = entry.getKey().isEmpty() ? GENERAL : SettingsSections.nameOf(entry.getKey());
			SectionBox box = new SectionBox(name);
			for (ConfigItemDescriptor item : entry.getValue())
			{
				JComponent row = row(item);
				if (row != null)
				{
					box.rows.add(new Row(row, (item.name() + " " + item.getItem().description() + " " + name).toLowerCase()));
					box.contents.add(row);
				}
			}
			addSection(box);
		}
	}

	private void addSection(SectionBox box)
	{
		box.header.setFont(FontManager.getRunescapeBoldFont());
		box.header.setHorizontalAlignment(JButton.LEFT);
		box.header.setFocusPainted(false);
		box.header.addActionListener(e -> setOpen(box, !box.open));
		box.contents.setLayout(new BoxLayout(box.contents, BoxLayout.Y_AXIS));
		box.contents.setBorder(new EmptyBorder(4, 4, 6, 0));
		box.panel.add(box.header, BorderLayout.NORTH);
		box.panel.add(box.contents, BorderLayout.CENTER);
		box.panel.setBorder(new EmptyBorder(0, 0, 4, 0));
		box.panel.setAlignmentX(LEFT_ALIGNMENT);
		setOpen(box, false);
		sections.add(box);
		list.add(box.panel);
	}

	private void setOpen(SectionBox box, boolean open)
	{
		box.open = open;
		box.header.setText((open ? "▾ " : "▸ ") + box.name);
		applyFilter();
	}

	private void setAllOpen(boolean open)
	{
		for (SectionBox box : sections)
		{
			box.open = open;
			box.header.setText((open ? "▾ " : "▸ ") + box.name);
		}
		applyFilter();
	}

	/** Hides rows that do not match the search, and sections left with none; opens sections while searching. */
	private void applyFilter()
	{
		String query = search.getText().trim().toLowerCase();
		boolean searching = !query.isEmpty();
		for (SectionBox box : sections)
		{
			boolean any = false;
			for (Row row : box.rows)
			{
				boolean match = !searching || row.text.contains(query);
				row.panel.setVisible(match);
				any |= match;
			}
			box.panel.setVisible(!searching || any);
			box.contents.setVisible(searching ? any : box.open);
		}
		list.revalidate();
		list.repaint();
	}

	// Rows

	/** A row for one setting, or null for a type the side panel cannot edit. */
	private JComponent row(ConfigItemDescriptor item)
	{
		Type type = item.getType();
		String key = item.key();
		JLabel label = new JLabel("<html>" + item.name() + "</html>");
		label.setToolTipText("<html><body style='width: 220px'>" + item.getItem().description()
			+ "<br><br>Right-click to reset to the default.</body></html>");
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeSmallFont());

		JComponent field;
		boolean wide;
		if (type == boolean.class || type == Boolean.class)
		{
			JCheckBox box = new JCheckBox();
			box.addActionListener(e -> save(key, box.isSelected()));
			refreshers.put(key, () -> box.setSelected(Boolean.TRUE.equals(value(key, Boolean.class))));
			field = box;
			wide = false;
		}
		else if (type == int.class || type == Integer.class)
		{
			Range range = item.getRange();
			int min = range == null ? 0 : range.min();
			int max = range == null ? Integer.MAX_VALUE : range.max();
			Integer current = value(key, Integer.class);
			int start = Math.max(min, Math.min(max, current == null ? min : current));
			JSpinner spinner = new JSpinner(new SpinnerNumberModel(start, min, max, 1));
			spinner.addChangeListener(e -> save(key, spinner.getValue()));
			refreshers.put(key, () ->
			{
				Integer v = value(key, Integer.class);
				if (v != null && !v.equals(spinner.getValue()))
				{
					spinner.setValue(Math.max(min, Math.min(max, v)));
				}
			});
			JPanel holder = new JPanel(new BorderLayout(4, 0));
			holder.add(spinner, BorderLayout.CENTER);
			if (item.getUnits() != null)
			{
				holder.add(small(new JLabel(item.getUnits().value().trim())), BorderLayout.EAST);
			}
			field = holder;
			wide = false;
		}
		else if (type == Color.class)
		{
			JButton swatch = new JButton();
			swatch.setToolTipText("Click to pick a color");
			boolean alpha = item.getAlpha() != null;
			refreshers.put(key, () ->
			{
				Color c = value(key, Color.class);
				if (c != null)
				{
					swatch.setBackground(c);
					swatch.setText(alpha ? String.format("%d%%", Math.round(c.getAlpha() * 100 / 255f)) : "");
				}
			});
			swatch.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (!SwingUtilities.isLeftMouseButton(e))
					{
						return;
					}
					RuneliteColorPicker picker = colorPickerManager.create(swatch, swatch.getBackground(), item.name(),
						!alpha);
					picker.setOnColorChange(c ->
					{
						swatch.setBackground(c);
						save(key, c);
					});
					picker.setVisible(true);
				}
			});
			field = swatch;
			wide = false;
		}
		else if (type instanceof Class && ((Class<?>) type).isEnum())
		{
			Object[] options = ((Class<?>) type).getEnumConstants();
			JComboBox<Object> combo = new JComboBox<>(options);
			combo.setRenderer(new DefaultListCellRenderer()
			{
				@Override
				public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected,
					boolean focus)
				{
					return super.getListCellRendererComponent(list, readable(value), index, selected, focus);
				}
			});
			combo.addActionListener(e -> save(key, combo.getSelectedItem()));
			refreshers.put(key, () ->
			{
				Object v = value(key, type);
				if (v != null && v != combo.getSelectedItem())
				{
					combo.setSelectedItem(v);
				}
			});
			field = combo;
			wide = true;
		}
		else if (type == String.class)
		{
			JTextField text = new JTextField();
			Runnable store = () -> save(key, text.getText());
			text.addActionListener(e -> store.run());
			text.addFocusListener(new FocusAdapter()
			{
				@Override
				public void focusLost(FocusEvent e)
				{
					store.run();
				}
			});
			refreshers.put(key, () ->
			{
				String v = value(key, String.class);
				if (v != null && !v.equals(text.getText()))
				{
					text.setText(v);
				}
			});
			field = text;
			wide = true;
		}
		else if (type == Keybind.class)
		{
			field = hotkey(key);
			wide = true;
		}
		else
		{
			return null;
		}

		JPanel row = new JPanel(new BorderLayout(6, 2));
		row.setBorder(BorderFactory.createEmptyBorder(3, 0, 3, 0));
		row.add(label, wide ? BorderLayout.NORTH : BorderLayout.CENTER);
		row.add(field, wide ? BorderLayout.CENTER : BorderLayout.EAST);
		row.setAlignmentX(LEFT_ALIGNMENT);
		addReset(label, key);
		addReset(row, key);

		updating = true;
		try
		{
			Runnable refresher = refreshers.get(key);
			if (refresher != null)
			{
				refresher.run();
			}
		}
		finally
		{
			updating = false;
		}
		return row;
	}

	/** A button that records the next key pressed as the hotkey; Backspace or Delete clears it. */
	private JComponent hotkey(String key)
	{
		JButton button = new JButton();
		boolean[] waiting = {false};
		refreshers.put(key, () ->
		{
			Keybind v = value(key, Keybind.class);
			button.setText(v == null || Keybind.NOT_SET.equals(v) ? "Not set" : v.toString());
		});
		button.setToolTipText("Click, then press the keys; Backspace or Delete clears it");
		button.addActionListener(e ->
		{
			waiting[0] = true;
			button.setText("Press keys...");
			button.requestFocusInWindow();
		});
		button.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				if (!waiting[0])
				{
					return;
				}
				e.consume();
				Keybind bind = e.getKeyCode() == KeyEvent.VK_BACK_SPACE || e.getKeyCode() == KeyEvent.VK_DELETE
					? Keybind.NOT_SET : new Keybind(e);
				// Keep waiting while only a modifier is held, so combinations can be pressed
				if (Keybind.getModifierForKeyCode(e.getKeyCode()) == null || bind == Keybind.NOT_SET)
				{
					waiting[0] = false;
				}
				save(key, bind);
				button.setText(Keybind.NOT_SET.equals(bind) ? "Not set" : bind.toString());
			}
		});
		button.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				if (waiting[0])
				{
					waiting[0] = false;
					settingChanged(key);
				}
			}
		});
		return button;
	}

	private void addReset(JComponent component, String key)
	{
		JPopupMenu menu = new JPopupMenu();
		JMenuItem reset = new JMenuItem("Reset to default");
		reset.addActionListener(e ->
		{
			configManager.unsetConfiguration(InventoryHoverHighlightConfig.GROUP, key);
			// Store the default again, so the setting reads like the others
			configManager.setDefaultConfiguration(config, false);
			settingChanged(key);
		});
		menu.add(reset);
		component.setComponentPopupMenu(menu);
	}

	private void save(String key, Object value)
	{
		if (!updating && value != null)
		{
			configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, key, value);
		}
	}

	private <T> T value(String key, Type type)
	{
		try
		{
			return configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, key, type);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** An option's name as words, like "Horizontal band" for HORIZONTAL_BAND. */
	private static String readable(Object value)
	{
		if (!(value instanceof Enum))
		{
			return value == null ? "" : value.toString();
		}
		String words = ((Enum<?>) value).name().replace('_', ' ').toLowerCase();
		return words.isEmpty() ? words : Character.toUpperCase(words.charAt(0)) + words.substring(1);
	}

	private static JLabel small(JLabel label)
	{
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}
}

package com.inventoryhover;

import java.awt.Color;
import java.awt.Paint;
import java.awt.PaintContext;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Transparency;
import java.awt.geom.AffineTransform;
import java.awt.geom.NoninvertibleTransformException;
import java.awt.geom.Rectangle2D;
import java.awt.image.ColorModel;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;

/**
 * Paints the spotlight gradient in shapes other than a circle: each pixel takes
 * the gradient's color at its distance from the mouse, measured the way the
 * gradient type says, such as the larger of the two axes for a square.
 */
final class SpotlightPaint implements Paint
{
	/** Colors along the gradient from the center to its outer radius. */
	private static final int STEPS = 512;

	private final InventoryHoverHighlightConfig.SpotlightType type;
	private final InventoryHoverHighlightConfig.SpotlightMotion motion;
	private final double seconds;
	private final double centerX;
	private final double centerY;
	private final double radius;
	private final int[] lookup = new int[STEPS + 1];

	SpotlightPaint(InventoryHoverHighlightConfig.SpotlightType type, InventoryHoverHighlightConfig.SpotlightMotion motion,
		double seconds, double centerX, double centerY, float radius, float[] stops, Color[] colors)
	{
		this.type = type;
		this.motion = motion;
		this.seconds = seconds;
		this.centerX = centerX;
		this.centerY = centerY;
		this.radius = Math.max(1, radius);
		for (int i = 0; i <= STEPS; i++)
		{
			lookup[i] = colorAt((float) i / STEPS, stops, colors).getRGB();
		}
	}

	/** Whether the type, or the motion, needs the paint drawn pixel by pixel. */
	static boolean needsPaint(InventoryHoverHighlightConfig.SpotlightType type, InventoryHoverHighlightConfig.SpotlightMotion motion)
	{
		boolean circle = type == null || type == InventoryHoverHighlightConfig.SpotlightType.CIRCLE;
		boolean still = motion == null || motion == InventoryHoverHighlightConfig.SpotlightMotion.NONE;
		return !circle || !still;
	}

	/**
	 * Distance from the center the way a gradient type measures it, in pixels,
	 * with the shape turned or rippled by its motion. Used for the whole
	 * gradient, falloff included, so the shape carries on to its outer edge.
	 */
	static double distance(InventoryHoverHighlightConfig.SpotlightType type, InventoryHoverHighlightConfig.SpotlightMotion motion,
		double seconds, double dx, double dy)
	{
		if (motion == InventoryHoverHighlightConfig.SpotlightMotion.SPIN)
		{
			double angle = seconds * 0.8;
			double cos = Math.cos(angle);
			double sin = Math.sin(angle);
			double x = dx * cos - dy * sin;
			dy = dx * sin + dy * cos;
			dx = x;
		}
		double d = distance(type, dx, dy);
		if (motion == InventoryHoverHighlightConfig.SpotlightMotion.WOBBLE)
		{
			d /= 1 + 0.08 * Math.sin(6 * Math.atan2(dy, dx) + seconds * 3);
		}
		return d;
	}

	/** Distance from the center the way a gradient type measures it, in pixels. */
	static double distance(InventoryHoverHighlightConfig.SpotlightType type, double dx, double dy)
	{
		if (type == null)
		{
			return Math.hypot(dx, dy);
		}
		switch (type)
		{
			case ELLIPSE:
				return Math.hypot(dx / 1.6, dy);
			case SQUARE:
				return Math.max(Math.abs(dx), Math.abs(dy));
			case DIAMOND:
				return (Math.abs(dx) + Math.abs(dy)) * 0.75;
			case STAR:
				// Five points: farther reach along each point's direction
				return Math.hypot(dx, dy) / (1 + 0.35 * Math.cos(5 * Math.atan2(dy, dx) + Math.PI / 2));
			case HEXAGON:
				return Math.max(Math.abs(dy), Math.abs(dx) * 0.866 + Math.abs(dy) * 0.5);
			case CROSS:
				return Math.min(Math.abs(dx), Math.abs(dy)) * 1.4;
			case FLOWER:
				return Math.hypot(dx, dy) / (1 + 0.25 * Math.cos(6 * Math.atan2(dy, dx)));
			case VERTICAL_BAND:
				return Math.abs(dx);
			case HORIZONTAL_BAND:
				return Math.abs(dy);
			default:
				return Math.hypot(dx, dy);
		}
	}

	/**
	 * How much of the gradient's opacity a pattern keeps at a point, 0 to 1.
	 * Patterns sit on a circle and only change brightness, so the falloff still
	 * shows through them.
	 */
	static double pattern(InventoryHoverHighlightConfig.SpotlightType type, double seconds, double dx, double dy,
		double radius)
	{
		if (type == null)
		{
			return 1;
		}
		double d = Math.hypot(dx, dy);
		switch (type)
		{
			case RINGS:
			{
				double spacing = Math.max(8, radius / 6);
				return 0.55 + 0.45 * Math.cos(2 * Math.PI * (d / spacing - seconds * 0.5));
			}
			case SPIRAL:
			{
				double spacing = Math.max(10, radius / 4);
				double turn = Math.atan2(dy, dx) / (2 * Math.PI);
				return 0.5 + 0.5 * Math.cos(2 * Math.PI * (d / spacing + turn * 3 - seconds * 0.4));
			}
			case RADAR:
			{
				// A bright wedge turning about once every three seconds, fading behind it
				double behind = (seconds * 2.1 - Math.atan2(dy, dx)) % (2 * Math.PI);
				if (behind < 0)
				{
					behind += 2 * Math.PI;
				}
				return 0.3 + 0.7 * Math.max(0, 1 - behind / (2 * Math.PI * 0.4));
			}
			default:
				return 1;
		}
	}

	/** A gradient's color at a share of its radius, from its stops. */
	static Color colorAt(float at, float[] stops, Color[] colors)
	{
		at = Math.max(0, Math.min(1, at));
		for (int i = 1; i < stops.length; i++)
		{
			if (at <= stops[i])
			{
				float span = stops[i] - stops[i - 1];
				return mix(colors[i - 1], colors[i], span <= 0 ? 1f : (at - stops[i - 1]) / span);
			}
		}
		return colors[colors.length - 1];
	}

	/** A color part way from one to another, alpha included. */
	static Color mix(Color a, Color b, float t)
	{
		t = Math.max(0f, Math.min(1f, t));
		return new Color(
			Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	@Override
	public PaintContext createContext(ColorModel cm, Rectangle deviceBounds, Rectangle2D userBounds,
		AffineTransform xform, RenderingHints hints)
	{
		AffineTransform toUser;
		try
		{
			toUser = xform.createInverse();
		}
		catch (NoninvertibleTransformException e)
		{
			toUser = new AffineTransform();
		}
		AffineTransform inverse = toUser;
		ColorModel model = ColorModel.getRGBdefault();
		return new PaintContext()
		{
			@Override
			public void dispose()
			{
			}

			@Override
			public ColorModel getColorModel()
			{
				return model;
			}

			@Override
			public Raster getRaster(int x, int y, int w, int h)
			{
				WritableRaster raster = model.createCompatibleWritableRaster(w, h);
				int[] pixels = new int[w * h];
				double[] point = new double[2];
				for (int row = 0; row < h; row++)
				{
					for (int col = 0; col < w; col++)
					{
						point[0] = x + col + 0.5;
						point[1] = y + row + 0.5;
						inverse.transform(point, 0, point, 0, 1);
						double dx = point[0] - centerX;
						double dy = point[1] - centerY;
						double share = distance(type, motion, seconds, dx, dy) / radius;
						int index = share >= 1 ? STEPS : (int) (share * STEPS);
						int argb = lookup[index];
						double keep = pattern(type, seconds, dx, dy, radius);
						if (keep < 1)
						{
							int alpha = (int) ((argb >>> 24) * keep);
							argb = (alpha << 24) | (argb & 0xFFFFFF);
						}
						pixels[row * w + col] = argb;
					}
				}
				raster.setDataElements(0, 0, w, h, pixels);
				return raster;
			}
		};
	}

	@Override
	public int getTransparency()
	{
		return Transparency.TRANSLUCENT;
	}
}

package com.inventoryhover;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

/**
 * Gear switch practice: lights up random empty inventory slots and times how
 * fast and how cleanly they are all clicked. Runs on the client thread; the
 * side panel only reads the immutable summaries.
 */
class SwitchPractice
{
	/** One finished round. */
	static class Round
	{
		/** From the targets lighting up to the first click. */
		final long reactMillis;
		/** From the first click to the last target clicked. */
		final long switchMillis;
		/** Game ticks the clicks were spread over, 1 when all landed in one tick. */
		final int ticks;
		final int hits;
		final int misses;
		/** Whether the time limit ran out before every target was clicked. */
		final boolean timedOut;

		Round(long reactMillis, long switchMillis, int ticks, int hits, int misses, boolean timedOut)
		{
			this.reactMillis = reactMillis;
			this.switchMillis = switchMillis;
			this.ticks = ticks;
			this.hits = hits;
			this.misses = misses;
			this.timedOut = timedOut;
		}
	}

	/** Averages over the rounds of one practice session, kept for the progress chart. */
	static class Summary
	{
		long time;
		int rounds;
		double reactMillis;
		double switchMillis;
		long bestSwitchMillis;
		double ticks;
		/** Finished rounds done within one tick, 0 to 100. */
		double oneTickRate;
		int timeouts;
		/** Hits as a share of all clicks, 0 to 100. */
		double accuracy;
	}

	enum Result
	{
		HIT,
		MISS,
		IGNORED
	}

	private final Random random = new Random();

	/** Target slot indexes; true once clicked. Insertion order is the click order in ordered mode. */
	private final Map<Integer, Boolean> targets = new LinkedHashMap<>();

	private final List<Round> rounds = new ArrayList<>();

	private long roundStart;
	private long firstClick;
	private int firstTick;
	private int misses;

	/** When the next round may start, in nanoTime. */
	private long nextRound;

	private long sessionStart;

	/** Last finished round, or null. */
	Round lastRound;

	/** Settings, set by the overlay each frame. */
	long roundDelay;
	long extraDelay;
	long timeLimit;
	boolean ordered;
	int roundsPerSession;

	boolean isActive()
	{
		return sessionStart != 0;
	}

	void start(long now)
	{
		reset();
		sessionStart = System.currentTimeMillis();
		nextRound = now;
	}

	/** Ends the session; returns its summary, or null when no round was finished. */
	Summary stop()
	{
		Summary summary = summary();
		reset();
		return summary;
	}

	private void reset()
	{
		targets.clear();
		rounds.clear();
		lastRound = null;
		firstClick = 0;
		misses = 0;
		sessionStart = 0;
	}

	/** Whether the set number of rounds is done, so the session should end. */
	boolean isComplete()
	{
		return isActive() && roundsPerSession > 0 && rounds.size() >= roundsPerSession;
	}

	/** Ends a round that ran out of time, then starts a new one once the pause is over. */
	void update(List<Integer> emptySlots, int count, long now, int tick)
	{
		if (!isActive() || isComplete())
		{
			return;
		}

		if (!targets.isEmpty())
		{
			if (timeLimit > 0 && now - roundStart >= timeLimit)
			{
				int hits = (int) targets.values().stream().filter(b -> b).count();
				misses += targets.size() - hits;
				finishRound(now, tick, hits, true);
			}
			return;
		}

		if (now < nextRound || emptySlots.isEmpty())
		{
			return;
		}

		List<Integer> pool = new ArrayList<>(emptySlots);
		Collections.shuffle(pool, random);
		for (int i = 0; i < Math.min(count, pool.size()); i++)
		{
			targets.put(pool.get(i), false);
		}
		roundStart = now;
		firstClick = 0;
		misses = 0;
	}

	/**
	 * Scores a click in the inventory: a hit on a target not clicked yet (the
	 * next one in ordered mode), a miss anywhere else. Clicks between rounds are
	 * ignored.
	 */
	Result click(int slot, long now, int tick)
	{
		if (!isActive() || targets.isEmpty())
		{
			return Result.IGNORED;
		}

		if (firstClick == 0)
		{
			firstClick = now;
			firstTick = tick;
		}

		Boolean clicked = targets.get(slot);
		if (clicked == null || clicked || (ordered && slot != nextTarget()))
		{
			misses++;
			return Result.MISS;
		}

		targets.put(slot, true);
		if (!targets.containsValue(false))
		{
			finishRound(now, tick, targets.size(), false);
		}
		return Result.HIT;
	}

	private void finishRound(long now, int tick, int hits, boolean timedOut)
	{
		long first = firstClick == 0 ? now : firstClick;
		Round round = new Round(
			(first - roundStart) / 1_000_000,
			(now - first) / 1_000_000,
			firstClick == 0 ? 0 : tick - firstTick + 1,
			hits,
			misses,
			timedOut);
		rounds.add(round);
		lastRound = round;
		targets.clear();
		nextRound = now + roundDelay + (long) (random.nextDouble() * extraDelay);
	}

	/** The slot to click next in ordered mode, or -1. */
	int nextTarget()
	{
		for (Map.Entry<Integer, Boolean> target : targets.entrySet())
		{
			if (!target.getValue())
			{
				return target.getKey();
			}
		}
		return -1;
	}

	/** Target slot indexes mapped to whether they are clicked, in light-up order. */
	Map<Integer, Boolean> targets()
	{
		return targets;
	}

	/** Share of the time limit left in the running round, 1 to 0; 1 with no limit or no round. */
	double timeLeft(long now)
	{
		if (timeLimit <= 0 || targets.isEmpty())
		{
			return 1;
		}
		return Math.max(0, 1 - (double) (now - roundStart) / timeLimit);
	}

	int roundCount()
	{
		return rounds.size();
	}

	/** Averages of this session so far, or null with no finished round. */
	Summary summary()
	{
		if (rounds.isEmpty())
		{
			return null;
		}

		Summary summary = new Summary();
		summary.time = sessionStart;
		summary.rounds = rounds.size();
		summary.bestSwitchMillis = Long.MAX_VALUE;
		int hits = 0;
		int missed = 0;
		int finished = 0;
		int oneTick = 0;
		for (Round round : rounds)
		{
			hits += round.hits;
			missed += round.misses;
			if (round.timedOut)
			{
				summary.timeouts++;
				continue;
			}
			finished++;
			summary.reactMillis += round.reactMillis;
			summary.switchMillis += round.switchMillis;
			summary.bestSwitchMillis = Math.min(summary.bestSwitchMillis, round.switchMillis);
			summary.ticks += round.ticks;
			if (round.ticks <= 1)
			{
				oneTick++;
			}
		}
		if (finished > 0)
		{
			summary.reactMillis /= finished;
			summary.switchMillis /= finished;
			summary.ticks /= finished;
			summary.oneTickRate = oneTick * 100.0 / finished;
		}
		else
		{
			summary.bestSwitchMillis = 0;
		}
		summary.accuracy = hits + missed == 0 ? 0 : hits * 100.0 / (hits + missed);
		return summary;
	}
}

package com.inventoryhover;

import java.awt.Color;
import java.lang.reflect.Type;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Hover, slot background, spotlight and miss dot settings of one tab, read by
 * the tab's key prefix. Resolved values are cached until a setting changes.
 */
@Singleton
class TabSettings
{
	static final String INVENTORY = "inv";
	static final String PRAYERS = "prayer";
	static final String SPELLS = "spell";

	static final List<String> PREFIXES = List.of(INVENTORY, PRAYERS, SPELLS);

	/** Config sections that hold tab settings. */
	static final Set<String> SECTIONS = Set.of(InventoryHoverHighlightConfig.invHoverSection, InventoryHoverHighlightConfig.invSpotlightSection, InventoryHoverHighlightConfig.invMissDotsSection, InventoryHoverHighlightConfig.prayerHoverSection, InventoryHoverHighlightConfig.prayerSpotlightSection, InventoryHoverHighlightConfig.prayerMissDotsSection, InventoryHoverHighlightConfig.spellHoverSection, InventoryHoverHighlightConfig.spellSpotlightSection, InventoryHoverHighlightConfig.spellMissDotsSection);

	static class Tab
	{
		InventoryHoverHighlightConfig.HighlightStyle style;
		Color outlineColor;
		Color fillColor;
		int outlineWidth;
		int cornerRadius;
		int hoverFade;
		int hoverDelay;
		boolean hideWhenMenuOpen;
		boolean discoMode;
		int discoInterval;
		boolean keepIconColors;
		/** Slot background color, or null when off. */
		Color slotBackground;
		boolean spotlight;
		int spotlightRadius;
		Color spotlightDim;
		Color spotlightGlow;
		int spotlightGlowSize;
		InventoryHoverHighlightConfig.SpotlightShape spotlightShape;
		InventoryHoverHighlightConfig.SpotlightType spotlightType;
		InventoryHoverHighlightConfig.SpotlightMotion spotlightMotion;
		InventoryHoverHighlightConfig.SpotlightEffect spotlightEffect;
		/** Where the effect shows; stored under the key "SpotlightEffectColor". */
		InventoryHoverHighlightConfig.EffectArea spotlightEffectArea;
		boolean spotlightEffectReplace;
		boolean spotlightEffectOnClick;
		/** The custom effect color; null when Custom effect color is off or the color is fully see-through. */
		Color spotlightEffectOverride;
		boolean spotlightClickResult;
		Color spotlightClickSuccessColor;
		Color spotlightClickMissColor;
		Color spotlightClickRefusedColor;
		int spotlightEffectSpeed;
		int spotlightEffectLength;
		int spotlightEffectSize;
		boolean spotlightEffectDetach;
		/** Inventory only: click bursts outside every panel too. */
		boolean spotlightClickAnywhere;
		int spotlightClickAnywhereDelay;
		boolean spotlightAlways;
		boolean spotlightDeadOnly;
		boolean spotlightFalloff;
		int spotlightFalloffDistance;
		int spotlightFalloffEnd;
		Color spotlightFalloffColor;
		int spotlightFalloffColorEnd;
		/** Null when fully see-through, meaning fade out to nothing. */
		Color spotlightFadeEndColor;
		boolean missDots;
		Color missDotColor;
		InventoryHoverHighlightConfig.MissDotShape missDotShape;
		boolean missDotHollow;
		int missDotSize;
		int missDotDuration;
	}

	private final ConfigManager configManager;
	private final Map<String, Tab> cache = new ConcurrentHashMap<>();

	@Inject
	TabSettings(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	Tab get(String prefix)
	{
		return cache.computeIfAbsent(prefix, this::resolve);
	}

	void invalidate()
	{
		cache.clear();
	}

	private Tab resolve(String p)
	{
		Tab tab = new Tab();
		tab.style = read(p + "Style", InventoryHoverHighlightConfig.HighlightStyle.class, InventoryHoverHighlightConfig.HighlightStyle.BOTH);
		tab.outlineColor = read(p + "OutlineColor", Color.class, new Color(255, 255, 255, 120));
		tab.fillColor = read(p + "FillColor", Color.class, new Color(98, 189, 125, 60));
		tab.outlineWidth = read(p + "OutlineWidth", int.class, 1);
		tab.cornerRadius = read(p + "CornerRadius", int.class, 4);
		tab.hoverFade = read(p + "HoverFade", int.class, 400);
		tab.hoverDelay = read(p + "HoverDelay", int.class, 0);
		tab.hideWhenMenuOpen = read(p + "HideWhenMenuOpen", boolean.class, false);
		tab.discoMode = read(p + "DiscoMode", boolean.class, false);
		tab.discoInterval = read(p + "DiscoInterval", int.class, 0);
		tab.keepIconColors = read(p + "KeepIconColors", boolean.class, false);
		tab.slotBackground = read(p + "SlotBackground", boolean.class, false)
			? read(p + "SlotBackgroundColor", Color.class, new Color(60, 60, 70, 90))
			: null;
		tab.spotlight = read(p + "Spotlight", boolean.class, false);
		tab.spotlightRadius = read(p + "SpotlightRadius", int.class, 90);
		tab.spotlightDim = read(p + "SpotlightDim", Color.class, new Color(0, 0, 0, 110));
		tab.spotlightGlow = read(p + "SpotlightGlow", Color.class, new Color(255, 255, 255, 45));
		tab.spotlightGlowSize = read(p + "SpotlightGlowSize", int.class, 30);
		tab.spotlightShape = read(p + "SpotlightShape", InventoryHoverHighlightConfig.SpotlightShape.class,
			InventoryHoverHighlightConfig.SpotlightShape.SMOOTH);
		tab.spotlightType = read(p + "SpotlightType", InventoryHoverHighlightConfig.SpotlightType.class,
			InventoryHoverHighlightConfig.SpotlightType.CIRCLE);
		tab.spotlightMotion = read(p + "SpotlightMotion", InventoryHoverHighlightConfig.SpotlightMotion.class,
			InventoryHoverHighlightConfig.SpotlightMotion.NONE);
		tab.spotlightEffect = read(p + "SpotlightEffect", InventoryHoverHighlightConfig.SpotlightEffect.class,
			InventoryHoverHighlightConfig.SpotlightEffect.NONE);
		tab.spotlightEffectArea = read(p + "SpotlightEffectColor", InventoryHoverHighlightConfig.EffectArea.class,
			InventoryHoverHighlightConfig.EffectArea.OVERLAY);
		tab.spotlightEffectReplace = read(p + "SpotlightEffectReplace", boolean.class, false);
		tab.spotlightEffectOnClick = read(p + "SpotlightEffectOnClick", boolean.class, false);
		tab.spotlightEffectOverride = read(p + "SpotlightEffectCustom", boolean.class, false)
			? visible(read(p + "SpotlightEffectOverride", Color.class, new Color(255, 255, 255, 200)))
			: null;
		tab.spotlightClickResult = read(p + "SpotlightClickResult", boolean.class, false);
		tab.spotlightClickSuccessColor = read(p + "SpotlightClickSuccessColor", Color.class, new Color(0, 255, 0, 200));
		tab.spotlightClickMissColor = read(p + "SpotlightClickMissColor", Color.class, new Color(255, 60, 60, 200));
		tab.spotlightClickRefusedColor = read(p + "SpotlightClickRefusedColor", Color.class, new Color(255, 220, 0, 200));
		tab.spotlightEffectSpeed = read(p + "SpotlightEffectSpeed", int.class, 100);
		tab.spotlightEffectLength = read(p + "SpotlightEffectLength", int.class, 1200);
		tab.spotlightEffectSize = read(p + "SpotlightEffectSize", int.class, 100);
		tab.spotlightEffectDetach = read(p + "SpotlightEffectDetach", boolean.class, false);
		tab.spotlightClickAnywhere = read(p + "SpotlightClickAnywhere", boolean.class, false);
		tab.spotlightClickAnywhereDelay = read(p + "SpotlightClickAnywhereDelay", int.class, 600);
		tab.spotlightAlways = read(p + "SpotlightAlways", boolean.class, false);
		tab.spotlightDeadOnly = read(p + "SpotlightDeadOnly", boolean.class, false);
		tab.spotlightFalloff = read(p + "SpotlightFalloff", boolean.class, false);
		tab.spotlightFalloffDistance = read(p + "SpotlightFalloffDistance", int.class, 250);
		tab.spotlightFalloffEnd = read(p + "SpotlightFalloffEnd", int.class, 400);
		tab.spotlightFalloffColor = read(p + "SpotlightFalloffColor", Color.class, new Color(0, 0, 0, 0));
		tab.spotlightFalloffColorEnd = read(p + "SpotlightFalloffColorEnd", int.class, 0);
		tab.spotlightFadeEndColor = visible(read(p + "SpotlightFadeEndColor", Color.class, new Color(0, 0, 0, 0)));
		tab.missDots = read(p + "MissDots", boolean.class, false);
		tab.missDotColor = read(p + "MissDotColor", Color.class, new Color(255, 40, 40, 200));
		tab.missDotShape = read(p + "MissDotShape", InventoryHoverHighlightConfig.MissDotShape.class, InventoryHoverHighlightConfig.MissDotShape.CIRCLE);
		tab.missDotHollow = read(p + "MissDotHollow", boolean.class, false);
		tab.missDotSize = read(p + "MissDotSize", int.class, 4);
		tab.missDotDuration = read(p + "MissDotDuration", int.class, 15);
		return tab;
	}

	/** A stored setting, or its default when it was never set. */
	@SuppressWarnings("unchecked")
	/** A color, or null when it is fully see-through. */
	private static Color visible(Color color)
	{
		return color == null || color.getAlpha() == 0 ? null : color;
	}

	private <T> T read(String key, Type type, T fallback)
	{
		Object value = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, key, type);
		return value == null ? fallback : (T) value;
	}
}

